insert into ui_strings (key, en, ar, status, context) values
  ('(admin command palette, no stable key)', 'Search allowed admin tools / {count} allowed result(s)', 'ابحث في أدوات الإدارة المسموح بها / {count} نتيجة مسموح بها', 'draft', 'authorized -> allowed'),
  ('(admin landing) approval error states', 'Some approval work could not load. / We could not read the request list, so we can''t say if it''s empty. / We could not read some request details, but the requests below are still shown.', 'بعض أعمال الاعتماد لم يتم تحميلها. / تعذّرت قراءة قائمة الطلبات، لذا لا يمكن الجزم بأنها فارغة. / تعذّرت قراءة بعض تفاصيل الطلبات، وتظل الطلبات أدناه ظاهرة.', 'draft', 'Removed ''partially unavailable''/''empty-queue claim'' jargon'),
  ('(admin landing) audit error', 'Recent changes are not available. / We could not read the Activity Log, so we can''t say there are no changes.', 'أحدث التغييرات غير متاحة. / تعذّرت قراءة سجل النشاط، لذا لا يمكن الجزم بعدم وجود تغييرات.', 'draft', 'unavailable -> not available; removed ''append-only audit source'' jargon'),
  ('(admin landing) authorization error', 'We could not check your access. / No approval or audit work is shown.', 'تعذّر التحقق من صلاحياتك. / لا تُعرض أي أعمال اعتماد أو تدقيق.', 'draft', 'Active voice, dropped ''workload'''),
  ('(admin landing) context caption', 'What is waiting on you, and what changed recently. Move between areas using the side menu. You only see the areas your role allows.', 'ما ينتظر إجراءً منك، وما تغيّر مؤخراً. تنقّل بين المجالات من القائمة الجانبية. تظهر لك فقط المجالات التي يسمح بها دورك.', 'draft', 'Simplified ''authorize''/''navigation''; inline text() call, no stable key'),
  ('(admin landing) no panels empty state', 'No admin panels are assigned to this role / Use the pages listed in the side menu.', 'لا توجد لوحات عمل إدارية مخصصة لهذا الدور / استخدم الصفحات المدرجة في القائمة الجانبية.', 'draft', 'Simplified ''administration work panels''/''authorized destinations in the navigation rail'''),
  ('(admin landing) recent-changes desc', 'Approved changes you''re allowed to see, taken directly from the Activity Log. Nothing here is summarized or guessed.', 'التغييرات المعتمدة التي يُسمح لك برؤيتها، مأخوذة مباشرة من سجل النشاط. لا شيء هنا مُلخّص أو مُخمَّن.', 'draft', 'authorized scope -> allowed to see; append-only simplified'),
  ('(admin landing) waiting-on-you desc + CTA', 'Submitted requests you are allowed to approve. Your own requests never appear here. Maker-checker rules protect every decision. / Open Awaiting Approval', 'الطلبات المُرسَلة التي يُسمح لك باعتمادها. لا تظهر هنا طلباتك الخاصة أبداً. تحمي قواعد فصل المُنشئ عن المعتمد كل قرار. / فتح قسم بانتظار الاعتماد', 'draft', 'authorized->allowed; CTA renamed to match Approval Queue -> Awaiting Approval glossary'),
  ('(committee action error)', 'The committee decision record is not turned on yet.', 'سجل قرار اللجنة غير مُفعَّل بعد.', 'draft', 'Removed exposed FEATURE_DECISION_DOSSIER env-var name and ''feature-flagged off'' jargon from the user-facing error string'),
  ('(inline copy(), no key) active alerts KPI', 'Active alerts', 'التنبيهات النشطة', 'draft', 'Summary KPI tile label. Was ''Active operational alerts''.'),
  ('(inline copy(), no key) live exceptions heading', 'Live exceptions', 'الاستثناءات المباشرة', 'draft', 'Was ''Live operational exceptions''.'),
  ('(inline copy(), no key) live positions link', 'Live positions', 'المواقع المباشرة', 'draft', 'Command-bar link to /operations/live. Was ''Live governed positions'' — dropped ''governed''.'),
  ('(inline copy(), no key) no-open-exceptions title+body', 'No open exceptions / No open exceptions in this scope.', 'لا توجد استثناءات مفتوحة / لا توجد استثناءات مفتوحة ضمن هذا النطاق.', 'draft', 'Was ''No open operational exceptions'' (title) and ''No open operational exceptions in this scope.'' (body).'),
  ('(inline copy(), no key) operational-state column header (x2)', 'Visit status', 'حالة الزيارة', 'draft', 'List-equivalent table column header and cell data-label. Was ''Operational state'' regression, both occurrences.'),
  ('(inline copy(), no key) records-you-can-see caption', 'Records you can see', 'السجلات التي يمكنك الاطلاع عليها', 'draft', 'Was ''Current RLS-scoped records''.'),
  ('(inline copy(), no key) summary heading', 'Summary', 'الملخص', 'draft', 'Was ''Operational summary''.'),
  ('(inline en/ar object, completionText.feedbackNote)', 'The server must provide a public link and a report link that matches your access.', 'يجب أن يوفر الخادم رابطًا عامًا ورابط تقرير يطابق صلاحياتك.', 'draft', 'Companion note; dropped ''token-scoped'' / ''permission-filtered'' jargon'),
  ('(inline en/ar object, completionText.reportsNote)', 'Report links appear once the server provides them.', 'تظهر روابط التقارير فقط بعد أن يوفّرها الخادم.', 'draft', 'Completion screen ''Feedback & report QR'' section; dropped ''Authorized'''),
  ('(inline error string, callPlanningTransition)', 'This Planning action is blocked by the current state or a system rule.', 'هذا الإجراء التخطيطي محظور بسبب الحالة الحالية أو قاعدة في النظام.', 'draft', '23514 guard-violation error surfaced to the user; dropped ''governed configuration'''),
  ('(inline error string, cancelVisit)', 'Cancellation is blocked by the current state or the cutoff time. Nothing was changed.', 'الإلغاء محظور بسبب الحالة الحالية أو الموعد النهائي. لم يتغيّر شيء.', 'draft', '23514 error for cancelVisit'),
  ('(inline error string, no key) authorizeOperationsExport RPC failure', 'This export could not be authorized, or it''s outside what you''re allowed to access. No file was generated.', 'تعذّر ترخيص هذا التصدير، أو أنه خارج ما يُسمح لك بالوصول إليه. لم يتم إنشاء أي ملف.', 'draft', 'authorizeOperationsExport() server-action error toast. Was ''Export authorization is unavailable or outside your permitted scope. No file was generated.'''),
  ('(inline error string, no key) decideActiveCancellation RPC failure', 'The cancellation could not be decided. It may be outside your Operations access, or no longer pending.', 'تعذّر اتخاذ قرار بشأن الإلغاء. قد يكون خارج نطاق وصولك في العمليات، أو لم يعد معلّقًا.', 'draft', 'Was ''The cancellation could not be decided. It may be outside your Operations scope or no longer pending.'' — ''scope'' replaced with ''access'' for consistency with the other decision-error messages.'),
  ('(inline error string, no key) decideGeoOverride RPC failure', 'This location exception could not be decided. It may have expired, be outside your Operations access, or no longer be pending.', 'تعذّر اتخاذ قرار بشأن استثناء الموقع هذا. قد يكون منتهي الصلاحية، خارج نطاق وصولك في العمليات، أو لم يعد معلّقًا.', 'draft', 'Was ''The override could not be decided. It may be expired, outside your Operations scope, or no longer pending.'''),
  ('(inline error string, no key) decideGeoOverride expired', 'No decision was saved — the location exception expired before Operations could act.', 'لم يتم حفظ أي قرار — انتهت صلاحية استثناء الموقع قبل أن تتمكن العمليات من التصرف.', 'draft', 'Was ''No decision was saved — the override expired before Operations could act.'''),
  ('(inline error string, no key) decideGeoOverride invalid decision', 'Invalid location exception decision.', 'قرار استثناء الموقع غير صالح.', 'draft', 'Was ''Invalid override decision.'' — realigned with ''location exception'' naming.'),
  ('(inline error string, no key) markNotificationHandled no-row-updated', 'Nothing was updated — this is outside what you can access, or it''s already handled.', 'لم يتم تحديث أي شيء — إما أن هذا خارج ما يمكنك الوصول إليه، أو أنه معالج بالفعل.', 'draft', 'Notification mark-handled failure toast. Was ''No row updated — outside your notification scope or already handled.'''),
  ('(inline error string, no key) updateActionFormStatus no-row-updated', 'Nothing was updated — this is outside what you can access, or it''s already closed.', 'لم يتم تحديث أي شيء — إما أن هذا خارج ما يمكنك الوصول إليه، أو أنه مغلق بالفعل.', 'draft', 'Corrective-action status update failure toast. Was ''No row updated — outside your RLS scope (actions_rw) or already closed.'' — raw RLS/table-name jargon was directly user-visible.'),
  ('(inline error string, removeVisitAttachment)', 'This attachment is already removed, or you don''t have permission to remove it (planner/ops only).', 'هذا المرفق تمت إزالته بالفعل، أو ليست لديك صلاحية لإزالته (للمخطط أو التشغيل فقط).', 'draft', 'removeVisitAttachment error; removed leaked ''RLS denied (va_update requires planner/ops)'''),
  ('(inline error string, rescheduleVisit)', 'Rescheduling is blocked by the current state or the cutoff time. Nothing was changed.', 'إعادة الجدولة محظورة بسبب الحالة الحالية أو الموعد النهائي. لم يتغيّر شيء.', 'draft', '23514 error for rescheduleVisit'),
  ('(inline error string, returnVisit)', 'Return reasons aren''t available right now (ERR-OPS-001) — nothing was changed.', 'أسباب الإرجاع غير متاحة الآن (ERR-OPS-001) — لم يتغيّر شيء.', 'draft', 'returnVisit error when lookup read fails'),
  ('(inline ok string, cancelVisit)', 'Visit cancelled. Audit and notification were saved.', 'تم إلغاء الزيارة. تم حفظ التدقيق والإشعار.', 'draft', 'Success toast for cancelVisit'),
  ('(inline ok string, duplicateVisit)', 'Duplicated into a new Draft. Execution evidence and review decisions were not copied.', 'تم إنشاء نسخة كمسودة جديدة. لم يتم نسخ أدلة التنفيذ أو قرارات المراجعة.', 'draft', 'Success toast for duplicateVisit'),
  ('(inline ok string, removeVisitAttachment)', 'Attachment removed. The file and its audit record are kept.', 'تمت إزالة المرفق. تم الاحتفاظ بالملف وسجل التدقيق الخاص به.', 'draft', 'Success toast; dropped ''soft delete'' jargon'),
  ('(inline ok string, repackageVisit)', 'Primary checklist changed. Link history is kept; audit and notification were saved.', 'تم تغيير قائمة التفتيش الأساسية. تم الاحتفاظ بسجل الروابط؛ وتم حفظ التدقيق والإشعار.', 'draft', 'Success toast for repackageVisit'),
  ('(inline ok string, republishVisit)', 'Republished. The same Visit ID was kept; audit and notification were saved.', 'أُعيد النشر. تم الاحتفاظ بنفس رقم الزيارة؛ وتم حفظ التدقيق والإشعار.', 'draft', 'Success toast for republish'),
  ('(inline ok string, rescheduleVisit)', 'Window rescheduled. Audit and notification were saved.', 'أُعيدت جدولة الموعد. تم حفظ التدقيق والإشعار.', 'draft', 'Success toast for rescheduleVisit'),
  ('(inline ok string, returnVisit)', 'Returned. The history, audit record, and notification were saved.', 'تم الإرجاع. تم حفظ السجل والتدقيق والإشعار.', 'draft', 'Success toast; dropped ''atomically … intent recorded'''),
  ('(inline ok string, updateVisitNotes)', 'Notes saved and recorded for audit.', 'تم حفظ الملاحظات وتسجيلها للتدقيق.', 'draft', 'Success toast for notes save'),
  ('(inline ok string, updateVisitType)', 'Visit type updated — only before start, and it''s recorded for audit.', 'تم تحديث نوع الزيارة — قبل بدء التنفيذ فقط، وهو مسجَّل للتدقيق.', 'draft', 'Success toast for visit-type update'),
  ('(inline string)', 'Provider not available — recorded as a test row only; no live provider is set up for this channel.', 'الجهة المزوّدة غير متاحة — سُجِّل كصف اختبار فقط؛ لا توجد جهة مزوّدة فعلية مُعدّة لهذه القناة.', 'draft', 'Test notification not-configured notice'),
  ('(inline string, loading.tsx)', 'Loading system operations…', 'جارٍ تحميل عمليات النظام…', 'draft', 'Route loading title'),
  ('(none — hardcoded literal, no i18n)', 'Only an active published template can be deactivated.', 'يمكن إلغاء تفعيل القوالب المنشورة النشطة فقط.', 'draft', 'deactivateTemplateVersion() error; dropped ''governed''.'),
  ('(none — hardcoded string, not i18n''d in this file)', 'Supervision data not available / We couldn''t load the queue. Nothing was changed.', 'بيانات الإشراف غير متاحة / تعذّر تحميل قائمة الانتظار. لم يتم تغيير أي بيانات.', 'draft', 'Two identical EmptyState title/body pairs (access-error and query-error paths) are hardcoded English with no t()/tr() call and no Arabic version anywhere in this file — simplified in place (''unavailable'' -> ''not available'', ''The queue could not be loaded'' -> ''We couldn''t load the queue''); AR authored here for the future i18n migration of this file.'),
  ('(none — inline {en,ar} object in client error boundary, not an i18n key)', 'Couldn’t load the package library / The request didn’t finish. We can’t tell if this is empty or an error. / Try again.', 'تعذّر تحميل مكتبة الحزم / لم يكتمل الطلب. لا يمكننا معرفة ما إذا كانت القائمة فارغة أو حدث خطأ. / إعادة المحاولة', 'draft', 'title/body/retry fields of a local ar/en copy object driven by a locale cookie check, not the t() helper.'),
  ('admin.access.banner.body', '54 policies apply the fixed RBAC matrix. Role grants are recorded automatically (this page''s own data passed through RLS to render).', 'تطبّق 54 سياسة مصفوفة RBAC الثابتة. تُسجَّل منح الأدوار تلقائياً (مرّت بيانات هذه الصفحة نفسها عبر أمن الصفوف لعرضها).', 'draft', 'Access banner body; frozen -> fixed'),
  ('admin.access.manage.error.body', 'The user roster remains visible, but access changes are not available because one or more approved sources could not be read.', 'تبقى قائمة المستخدمين مرئية، لكن تغييرات الوصول غير متاحة لأن مصدراً معتمداً أو أكثر تعذّرت قراءته.', 'draft', 'Access-manage sources-unavailable body'),
  ('admin.access.manage.error.title', 'Access details are not fully available.', 'تفاصيل الوصول غير متاحة بالكامل.', 'draft', 'Access-manage sources-unavailable title'),
  ('admin.access.manage.intro', 'Grant or revoke roles and direct capability overrides. Every change runs through the approved RPCs: the self-escalation guard blocks changes to your own access, the last remaining security administrator cannot be revoked, and every change is recorded in the activity log.', 'امنح أو ألغِ الأدوار وتجاوزات الصلاحيات المباشرة. يمر كل تغيير عبر إجراءات قاعدة البيانات المعتمدة: يمنع حارس التصعيد الذاتي تغيير وصولك الخاص، ولا يمكن إلغاء آخر مسؤول أمان متبقٍ، ويُسجَّل كل تغيير في سجل النشاط.', 'draft', 'Access management panel intro'),
  ('admin.access.permissions.error.body', 'We couldn''t verify your access-management permissions. All write controls are turned off; reload the page.', 'تعذّر التحقق من صلاحيات إدارة الوصول لديك. جميع عناصر التحكم في الكتابة معطّلة؛ أعد تحميل الصفحة.', 'draft', 'Access permissions error body'),
  ('admin.access.permissions.error.title', 'Permissions not available.', 'الصلاحيات غير متاحة.', 'draft', 'Access permissions error title'),
  ('admin.access.rlsNote.manage', 'This roster is filtered to your access: users outside your visibility are absent, not hidden rows. Access changes use only approved server actions.', 'هذه القائمة مصفّاة حسب صلاحيتك: المستخدمون خارج نطاق رؤيتك غائبون، وليسوا صفوفاً مخفية. تستخدم تغييرات الوصول إجراءات خادم معتمدة فقط.', 'draft', 'Users tab footer note'),
  ('admin.access.rolecaps.error.body', 'The role catalogue remains visible, but capability changes are not available because an approved source could not be read.', 'يبقى كتالوج الأدوار مرئياً، لكن تغييرات الصلاحيات غير متاحة لأن مصدراً معتمداً تعذّرت قراءته.', 'draft', 'Role-capability sources-unavailable body'),
  ('admin.access.rolecaps.error.title', 'Role capability details are not available.', 'تفاصيل صلاحيات الدور غير متاحة.', 'draft', 'Role-capability sources-unavailable title'),
  ('admin.access.rolecaps.title', 'Role capabilities (permission map)', 'صلاحيات الدور (خريطة الأذونات)', 'draft', 'Role-capability panel title'),
  ('admin.access.roles.error.body', 'The authorized user roster remains visible, but role labels and all access changes are not available.', 'تبقى قائمة المستخدمين المصرَّح بهم مرئية، لكن تسميات الأدوار وجميع تغييرات الوصول غير متاحة.', 'draft', 'Roles error body'),
  ('admin.access.roles.error.title', 'Role details are not available.', 'تفاصيل الدور غير متاحة.', 'draft', 'Roles error title'),
  ('admin.bulkvio.dec032', 'Submitting is not available — DEC-032 blocks all real inspection submissions until the required database fix is approved and live. No violation will be issued from this page.', 'الإرسال غير متاح — يمنع القرار DEC-032 جميع عمليات إرسال التفتيش الفعلية حتى اعتماد ونشر إصلاح قاعدة البيانات المطلوب. لن تُصدر أي مخالفة من هذه الصفحة.', 'draft', 'Blocked-submission notice; ''database digest migration'' -> ''database fix'''),
  ('admin.bulkvio.error.ack', 'Review and confirm the impact summary.', 'راجع ملخص الأثر وأقر به.', 'draft', 'acknowledgement_required error text'),
  ('admin.bulkvio.error.conflict', 'This request ID was already used with different inputs. Start a new request.', 'استُخدم معرف الطلب هذا سابقًا بمدخلات مختلفة. ابدأ طلبًا جديدًا.', 'draft', 'idempotency_conflict error text'),
  ('admin.bulkvio.error.dec032', 'No change was made. DEC-032 blocks this submission until the required database fix is approved and live.', 'لم يتم إجراء أي تغيير. يمنع القرار DEC-032 هذا الإرسال حتى اعتماد إصلاح قاعدة البيانات المطلوب ونشره.', 'draft', 'dec032_blocked error text'),
  ('admin.bulkvio.error.denied', 'Your role cannot issue multiple violations at once.', 'لا يسمح دورك بإصدار مخالفات متعددة.', 'draft', 'not_authorized error text'),
  ('admin.bulkvio.error.invalid', 'Select factories, a violation and a checklist version.', 'حدد المنشآت والمخالفة وإصدار قائمة تفتيش.', 'draft', 'invalid_request error text'),
  ('admin.bulkvio.error.package', 'The selected checklist version is not locked, published and active.', 'إصدار قائمة التفتيش المحدد ليس مقفلًا ومنشورًا ونشطًا.', 'draft', 'package_version_invalid error text'),
  ('admin.bulkvio.error.violation', 'The selected violation is not an active, approved violation.', 'المخالفة المحددة ليست مخالفة معتمدة ونشطة.', 'draft', 'governed_violation_required error text; dropped ''governed'''),
  ('admin.bulkvio.error.write', 'Issuing failed. No successful result is claimed.', 'فشل الإصدار. لا يُدّعى تحقيق نتيجة ناجحة.', 'draft', 'write_failed error text'),
  ('admin.bulkvio.factoriesError', 'The factory list is not available in this environment.', 'قائمة المنشآت غير متاحة في هذه البيئة.', 'draft', '''establishment registry'' -> ''factory list'''),
  ('admin.bulkvio.packageLabel', 'Locked, published and active checklist version', 'إصدار قائمة تفتيش مقفل ومنشور ونشط', 'draft', '''package version'' -> ''checklist version'''),
  ('admin.bulkvio.packagePlaceholder', '— select an eligible checklist version', '— حدد إصدار قائمة تفتيش مؤهلًا', 'draft', 'Checklist-version select placeholder'),
  ('admin.bulkvio.packagesError', 'Published checklist versions are not available in this environment.', 'إصدارات قوائم التفتيش المنشورة غير متاحة في هذه البيئة.', 'draft', '''package versions'' -> ''checklist versions'''),
  ('admin.bulkvio.partialWarning', 'Not everything succeeded — check the failed rows below before assuming this batch is done.', 'لم تنجح جميع الأهداف — راجع الصفوف الفاشلة أدناه قبل افتراض اكتمال هذه الدفعة.', 'draft', 'Partial-success warning'),
  ('admin.bulkvio.previewBody', 'Read-only preview: {n} factory/factories are selected for one {level} violation ({code} · {penalty}). No inspection or violation can be created while DEC-032 remains open.', 'معاينة للقراءة فقط: تم تحديد {n} منشأة/منشآت لمخالفة واحدة من نوع {level} ({code} · {penalty}). لا يمكن إنشاء تفتيش أو مخالفة ما دام القرار DEC-032 مفتوحًا.', 'draft', 'Impact-summary body; ''establishment(s)'' -> ''factory/factories'''),
  ('admin.bulkvio.searchFactory', 'Search factories', 'البحث عن المنشآت', 'draft', '''establishments'' -> ''factories'''),
  ('admin.bulkvio.submit', 'Issuing is not available — DEC-032', 'الإصدار غير متاح — DEC-032', 'draft', 'Submit-button blocked label'),
  ('admin.bulkvio.title', 'Issue Multiple Violations', 'إصدار مخالفات متعددة', 'draft', 'Renamed per glossary: Bulk Violation Issuance -> Issue Multiple Violations'),
  ('admin.bulkvio.unauthorized.body', 'Issuing multiple violations (DEC-L) is only available to Operations and Compliance Admin roles.', 'إصدار المخالفات المتعددة (DEC-L) متاح لدوري العمليات ومسؤول الامتثال فقط.', 'draft', 'Role-gate body'),
  ('admin.bulkvio.unauthorized.title', 'Allowed role required', 'يلزم دور مصرح له', 'draft', '''Authorized role required'' simplified'),
  ('admin.bulkvio.violationsError', 'The violation catalogue is not available in this environment.', 'كتالوج المخالفات غير متاح في هذه البيئة.', 'draft', 'Wording simplified'),
  ('admin.bulkvio.warnBody', 'You can review the eligible factories and mapped violations, but this page cannot create an inspection or violation until the submission bug is fixed.', 'يمكنك مراجعة المنشآت المؤهلة والمخالفات المرتبطة، لكن لا يمكن لهذا المسار إنشاء تفتيش أو مخالفة ما دام خلل بصمة الإرسال مفتوحًا.', 'draft', '''establishments'' -> ''factories'', ''submission digest defect'' -> ''submission bug'''),
  ('admin.bulkvio.warnTitle', 'Real issuing is blocked by DEC-032.', 'الإصدار الفعلي محظور بموجب DEC-032.', 'draft', 'Page-level DEC-032 warning title'),
  ('admin.ccr.register.heading', 'Request list', 'قائمة الطلبات', 'draft', '''register'' -> ''list'' for consistency'),
  ('admin.enf.rec.error.backendGuard', 'Recording a decision is not available yet — a safe database step still needs to be added.', 'تسجيل القرار غير متاح بعد — لا يزال يلزم إضافة خطوة آمنة في قاعدة البيانات.', 'draft', 'Decision-write blocked error'),
  ('admin.enf.rec.guardPending', 'Decision not available yet — a safe database step is still needed.', 'القرار غير متاح بعد — لا يزال يلزم خطوة آمنة في قاعدة البيانات.', 'draft', 'Per-row decision-blocked note'),
  ('admin.enf.rec.readonly.body', 'You can view this list. To decide, you need an Operations or Compliance Admin role — the database enforces this.', 'يمكنك عرض هذه القائمة؛ يتطلب اتخاذ القرار دور العمليات أو مسؤول الامتثال، وتفرض قاعدة البيانات ذلك.', 'draft', 'Read-only role banner; removed ''row-level security'''),
  ('admin.enf.rec.scopeBody', 'Decisions are read-only for now, until the database supports a safe decision step. A future approval will only record the recommendation decision — it will not apply a penalty, close a factory, send a legal notice, or skip the enforcement rules.', 'القرارات للقراءة فقط حاليًا، إلى أن تدعم قاعدة البيانات خطوة قرار آمنة. ستسجل الموافقة المستقبلية القرار بشأن التوصية فقط؛ ولن تطبق عقوبة أو تغلق منشأة أو ترسل إشعارًا قانونيًا أو تتجاوز قواعد الإنفاذ.', 'draft', 'Decision-scope note; dropped ''atomic guarded'' and ''governed enforcement configuration''; ''establishment'' -> ''factory'''),
  ('admin.factoryData.batchesError', 'Batch tracking details could not be read. Available sync-run facts are kept without a guessed file origin.', 'تعذّرت قراءة تفاصيل تتبّع الدفعة. تُحفظ حقائق تشغيل المزامنة المتاحة دون تخمين مصدر الملف.', 'draft', 'Sync/import history error'),
  ('admin.factoryData.configNotConnectivity', 'Setting it up is not the same as being connected.', 'إعداد الشيء لا يعني أنه متصل.', 'draft', 'Provider section footer'),
  ('admin.factoryData.controlPlane', 'Settings only.', 'إعدادات فقط.', 'draft', 'Factory data integration banner title'),
  ('admin.factoryData.factoriesError', 'The Factory list could not be read. Import and reconciliation history below may still be available.', 'تعذّرت قراءة قائمة المصانع. قد يبقى سجل الاستيراد والمطابقة أدناه متاحاً.', 'draft', 'Factory selector load error; regression fix registry -> Factory list'),
  ('admin.factoryData.masterData', 'Factory master-data controls', 'عناصر التحكم في بيانات المصنع الأساسية', 'draft', 'Master-data section heading'),
  ('admin.factoryData.masterDataHelp', 'These operations are always recorded in the Activity Log. They do not edit external CR, license, or plant identifiers.', 'تُسجَّل هذه العمليات دائماً في سجل النشاط. ولا تُعدِّل معرّفات السجل التجاري أو الترخيص أو المنشأة الخارجية.', 'draft', 'Master-data section help; glossary Audit Trail -> Activity Log applied'),
  ('admin.factoryData.noReconciliation', 'No reconciliation records visible to you. This is a checked, empty result. Staged does not mean imported.', 'لا توجد سجلات مطابقة مرئية لك. هذه نتيجة فارغة تم التحقق منها. الترحيل لا يعني الاستيراد.', 'draft', 'Reconciliation empty state'),
  ('admin.factoryData.noRejected', 'No rejected staged rows. This is a checked, empty result.', 'لا توجد صفوف مرفوضة مرحّلة. هذه نتيجة فارغة تم التحقق منها.', 'draft', 'Rejected rows empty state'),
  ('admin.factoryData.noRuns', 'No sync or import runs visible to you. This is a checked, empty result.', 'لا توجد عمليات مزامنة أو استيراد مرئية لك. هذه نتيجة فارغة تم التحقق منها.', 'draft', 'Sync/import history empty state'),
  ('admin.factoryData.noWritebackHelp', 'Everything saved here is recorded in SAQEEL only. No establishment or factory master-data change is sent to SENAI: the endpoint contract has no master-data write endpoint, so there is no path for one. Where SENAI stays the source of truth, this screen holds SAQEEL-side details as pending-integration scaffolding until an approved reconciliation runs — it does not change the source.', 'كل ما يُحفظ هنا يُسجَّل في SAQEEL فقط. لا يُرسَل أي تغيير في بيانات المنشأة أو المصنع الأساسية إلى SENAI: عقد نقطة الاتصال لا يحتوي على نقطة كتابة للبيانات الأساسية، فلا يوجد مسار لذلك. وحيث تبقى SENAI مصدر الحقيقة، تحتفظ هذه الشاشة ببيانات جانب SAQEEL كإطار مؤقت للتكامل إلى أن تُنفَّذ مطابقة معتمدة — دون تغيير المصدر.', 'draft', 'FND-007 no-writeback explanation'),
  ('admin.factoryData.openDossier', 'Open factory profile (read-only)', 'فتح ملف المصنع (للقراءة فقط)', 'draft', 'BANNED-TERM fix: dossier -> Factory profile (destination-page concept)'),
  ('admin.factoryData.providerHelp', 'The endpoint contract and its recorded live-call check are shown in', 'يظهر عقد نقطة الاتصال وحالة التحقق المسجلة من الاستدعاء الفعلي في', 'draft', 'Provider section help text'),
  ('admin.factoryData.reconciliationError', 'Reconciliation history could not be read. This is data that''s not available, not an empty history.', 'تعذّرت قراءة سجل المطابقة. هذه بيانات غير متاحة، وليست سجلاً فارغاً.', 'draft', 'Reconciliation error'),
  ('admin.factoryData.rowsError', 'Rejected staged rows could not be read. This is data that''s not available, not an empty rejection set.', 'تعذّرت قراءة الصفوف المرفوضة. هذه بيانات غير متاحة، وليست مجموعة رفض فارغة.', 'draft', 'Rejected rows error'),
  ('admin.factoryData.truth', 'Factory 360 profiles are read-only. Setting up a provider does not prove it''s connected. CSV rows stay staged until a separate, approved reconciliation, and source identifiers can''t be silently replaced.', 'ملفات Factory 360 للقراءة فقط. إعداد جهة مزوّدة لا يثبت اتصالها. تبقى صفوف CSV مرحّلة إلى أن تتم مطابقة منفصلة ومعتمدة، ولا يمكن استبدال المعرّفات المصدرية بصمت.', 'draft', 'Factory data integration banner body'),
  ('admin.items.r2.audit.body', 'Open Audit on one item to see its change history; broad access to the full audit table is not given.', 'افتح التدقيق على عنصر واحد لعرض سجل تغييراته؛ لا يُمنح وصول واسع لجدول التدقيق الكامل.', 'draft', 'Audit-section body'),
  ('admin.items.r2.audit.empty', 'No activity found for this item.', 'لم يُعثر على أي نشاط لهذا العنصر.', 'draft', 'Audit empty state'),
  ('admin.items.r2.audit.heading', 'Item history', 'سجل العنصر', 'draft', '''Scoped item audit'' -> ''Item history'''),
  ('admin.items.r2.audit.unavailable', 'History couldn''t load — reload to retry. This does not mean the history is empty.', 'تعذّر تحميل السجل — أعد التحميل للمحاولة مجدداً. هذا لا يعني أن السجل فارغ.', 'draft', 'Audit read failure'),
  ('admin.items.r2.empty.body', 'Items belong to regulation clauses and are reused across checklists (M09-002). Add the first item above.', 'تنتمي العناصر إلى بنود اللوائح وتُعاد استخدامها عبر قوائم التفتيش (M09-002). أضف العنصر الأول أعلاه.', 'draft', '''packages'' -> ''checklists'''),
  ('admin.items.r2.empty.title', 'No inspection items set up yet', 'لا توجد عناصر تفتيش بعد', 'draft', 'Empty catalogue title'),
  ('admin.items.r2.footer', 'Items belong to regulations and are reused across checklists (M09-002/007); deactivation keeps history (M09-014). Writes need the compliance_admin/form_admin role — the database is the authority. inspection_items row changes are logged (trg_audit_inspection_items).', 'تنتمي العناصر إلى اللوائح وتُعاد استخدامها عبر قوائم التفتيش (M09-002/007)؛ يحافظ إلغاء التفعيل على السجل (M09-014). تتطلب عمليات الكتابة دور compliance_admin/form_admin — قاعدة البيانات هي المرجع. تُسجَّل تغييرات صفوف inspection_items (trg_audit_inspection_items).', 'draft', 'Catalogue footer; removed ''RLS'''),
  ('admin.items.r2.form.evidenceSource', 'Configured policy — a fixed preset, not free text (M09-005/025).', 'سياسة مُهيّأة — نمط ثابت مسبق، وليس نصاً حراً (M09-005/025).', 'draft', 'Evidence-rule field hint; dropped ''governed'''),
  ('admin.items.r2.form.visibleWhenHint', 'Use the fixed key=value format.', 'استخدم صيغة key=value الثابتة.', 'draft', 'Conditional-visibility hint; dropped ''governed'''),
  ('admin.items.r2.preview.deactivated', 'This item is deactivated. It''s hidden from new checklist versions; existing history is kept.', 'هذا العنصر معطّل. وهو مخفي عن إصدارات قوائم التفتيش الجديدة؛ يُحفظ السجل الحالي.', 'draft', '''package versions'' -> ''checklist versions'''),
  ('admin.items.r2.preview.readonly', 'This shows the saved configuration only — nothing here can be edited.', 'يعرض هذا التهيئة المحفوظة فقط — لا يمكن تعديل أي شيء هنا.', 'draft', 'Runtime preview readonly note'),
  ('admin.items.r2.readonly.body', 'Your role can view item details, usage and runtime previews. Creating or changing active state needs a Compliance or Form Admin role, enforced by the server and the database.', 'يمكن لدورك عرض تفاصيل العنصر واستخدامه ومعاينات وقت التشغيل. يتطلب الإنشاء أو تغيير الحالة النشطة دور مسؤول الامتثال أو مسؤول النماذج، ويُفرض ذلك عبر الخادم وقاعدة البيانات.', 'draft', 'Read-only role banner; removed ''RLS'''),
  ('admin.notif.degraded.chip', 'register not available', 'السجل غير متاح', 'draft', 'Notification rules status chip'),
  ('admin.notif.empty.body', 'The read succeeded — the register is really empty. Create the first rule above.', 'نجحت القراءة — السجل فارغ فعلاً. أنشئ أول قاعدة أعلاه.', 'draft', 'Notification rules empty state; genuinely -> really'),
  ('admin.notif.escalationNote', 'SLA timers and escalation roles are stored as settings. Automatic breach-firing (a scheduled process that escalates when a timer runs out) is separate, and this screen does not build it.', 'تُخزَّن مؤقتات SLA وأدوار التصعيد كإعدادات. إطلاق الخرق التلقائي (عملية مجدولة تُصعِّد عند انتهاء المؤقت) منفصل، ولا تبنيه هذه الشاشة.', 'draft', 'Notification footer note'),
  ('admin.notif.readonly.body', 'You can view settings. Creating, publishing and deactivating rules need an admin settings role, and the system enforces this automatically.', 'يمكنك عرض الإعدادات. يتطلب إنشاء القواعد ونشرها وإلغاء تفعيلها دور إعدادات إداري، ويفرض النظام ذلك تلقائياً.', 'draft', 'Read-only-for-role banner'),
  ('admin.notif.rolesUnavailable', 'Recipient roles are not available. Rule creation is turned off; existing rules remain readable.', 'أدوار المستلمين غير متاحة. إنشاء القواعد معطّل؛ تبقى القواعد الحالية قابلة للقراءة.', 'draft', 'Notification roles error'),
  ('admin.permissionsUnavailable.body', 'We couldn''t check your settings permissions. Writes are turned off; reload the page.', 'تعذّر التحقق من صلاحيات الإعدادات لديك. الكتابة معطّلة؛ أعد تحميل الصفحة.', 'draft', 'Read-only banner body'),
  ('admin.permissionsUnavailable.title', 'Permissions not available', 'الصلاحيات غير متاحة', 'draft', 'Read-only banner title (also touched in access/page.tsx)'),
  ('admin.pkg.blockers.body', 'The designer creates ordered, bilingual sections, package-item rules, action forms, and template references. Publishing checks dependencies again and rejects circular conditions. Package footprint and fingerprint metrics, and visual simulation, are not built yet — there is no approved way to measure or simulate them.', 'يُنشئ المصمم أقساماً مرتبة وثنائية اللغة، وقواعد ربط الحزمة بالبنود، ونماذج إجراءات، ومراجع قوالب. يتحقق النشر من الاعتماديات مجدداً ويرفض الشروط الدائرية. مقاييس بصمة الحزمة ومحاكاتها المرئية غير مُنجَزة بعد — لا توجد طريقة معتمدة لقياسها أو محاكاتها.', 'draft', 'Dropped ''governed''/''unclaimed'' jargon; ''authors'' -> ''creates''.'),
  ('admin.pkg.empty.body', 'We found no packages. This page doesn’t support creating new packages, so there’s no create button here.', 'لم نجد أي حزم. لا تدعم هذه الصفحة إنشاء حزم جديدة، لذا لا يوجد زر إنشاء هنا.', 'draft', 'Active voice, plain words.'),
  ('admin.pkg.immutable.body', 'The system blocks edits to the definition and label. To change this package, create a new draft. Existing inspections stay pinned to the version they downloaded.', 'يمنع النظام تعديل التعريف والتسمية. لتغيير هذه الحزمة، أنشئ مسودة جديدة. تبقى عمليات التفتيش الحالية مرتبطة بالإصدار الذي حمّلته.', 'draft', '''database rejects'' -> ''system blocks''; shorter sentences.'),
  ('admin.pkg.immutable.title', 'Published version — locked.', 'إصدار منشور — مقفل.', 'draft', 'immutable -> locked.'),
  ('admin.pkg.impact.pinnedHint', 'Existing work stays on the version it downloaded. Publishing never switches it to a new version without notice.', 'يبقى العمل الحالي على الإصدار الذي حمّله. لا يُبدّل النشر أبداً إلى إصدار جديد دون إشعار.', 'draft', 'Dropped ''frozen''/''silently re-versions'' jargon.'),
  ('admin.pkg.impact.pinnedUnavailable', 'Active counts aren’t available, or they’re outside what you can see. This does not mean zero.', 'الأعداد النشطة غير متاحة، أو خارج ما يمكنك رؤيته. هذا لا يعني أنها صفر.', 'draft', '''In-flight'' -> ''Active''; dropped ''read scope'' jargon.'),
  ('admin.pkg.itemsUnavailable.body', 'Package versions and impact still show, but editing and field preview are paused because we couldn’t read the item data they depend on. This is not an empty catalogue.', 'لا تزال إصدارات الحزم وأثرها ظاهرة، لكن التعديل والمعاينة الميدانية متوقفان مؤقتاً لأننا لم نتمكن من قراءة بيانات البنود التي تعتمد عليها. هذا ليس كتالوجاً فارغاً.', 'draft', 'Active voice, simpler words.'),
  ('admin.pkg.itemsUnavailable.title', 'Item catalogue not available.', 'كتالوج البنود غير متاح.', 'draft', '''unavailable'' -> ''not available''.'),
  ('admin.pkg.loading', 'Loading package versions and their dependencies…', 'جارٍ تحميل إصدارات الحزم واعتمادياتها…', 'draft', 'Dropped ''governed'' before ''dependencies''.'),
  ('admin.pkg.overview.body', 'Drafts can be edited. Publishing checks dependencies and needs maker-checker approval. Published and locked definitions can’t be changed.', 'يمكن تعديل المسودات. يتحقق النشر من الاعتماديات ويحتاج اعتماد فصل المُعدّ عن المعتمد. لا يمكن تغيير التعريفات المنشورة والمقفلة.', 'draft', 'Active voice, short sentences; immutable -> can''t be changed.'),
  ('admin.pkg.overview.title', 'Inspection packages, tracked by version', 'حزم التفتيش، مُتتبَّعة حسب الإصدار', 'draft', 'Dropped ''governed'' per simple-English pass.'),
  ('admin.pkg.publish.hint', 'Publishing rechecks item, evidence, condition, violation, penalty and action-form dependencies. The approver must be a different person from the creator (RBAC-002).', 'يُعيد النشر التحقق من اعتماديات البنود والأدلة والشروط والمخالفات والعقوبات ونماذج الإجراءات. يجب أن يكون المعتمد شخصاً مختلفاً عن مُنشئ المسودة (RBAC-002).', 'draft', 'Kept RBAC-002 traceability code; simplified ''differ from'' to ''a different person from''.'),
  ('admin.pkg.publish.published', 'Version published. It can no longer be changed.', 'تم نشر الإصدار. لم يعد بالإمكان تغييره.', 'draft', 'immutable -> plain ''can no longer be changed''.'),
  ('admin.pkg.readonly.body', 'You can view versions, previews and publish impact. To create, save or publish, you need the compliance_admin or form_admin role. Navigation access alone does not give you write permission.', 'يمكنك عرض الإصدارات والمعاينات وأثر النشر. للإنشاء أو الحفظ أو النشر، تحتاج دور compliance_admin أو form_admin. الوصول للتنقل وحده لا يمنحك صلاحية الكتابة.', 'draft', 'Kept precise role identifiers compliance_admin/form_admin as-is; split sentence.'),
  ('admin.pkg.readonly.unknown', 'We couldn’t check your write permissions, so all edit controls are hidden. Reload to try again.', 'لم نتمكن من التحقق من صلاحيات الكتابة الخاصة بك، لذا أدوات التعديل كلها مخفية. أعد التحميل للمحاولة مرة أخرى.', 'draft', 'Dropped ''RLS remains authoritative'' dev-jargon; active voice.'),
  ('admin.pkg.stale', 'Data may have changed since this was last read. There is no fixed rule for how fresh it must be.', 'قد تكون البيانات تغيّرت منذ آخر قراءة لها. لا توجد قاعدة ثابتة لمدى حداثتها المطلوبة.', 'draft', '''no freshness threshold is defined'' -> plain wording.'),
  ('admin.recordDrawer.access.editUnavailable', 'Your session doesn''t have the access-management permission.', 'لا تملك جلستك صلاحية إدارة الوصول.', 'draft', 'Access-edit-unavailable drawer reason'),
  ('admin.recordDrawer.integration.editUnavailable', 'The endpoint registry has no approved edit workflow on this route. Connection-specific data actions stay on their approved destinations.', 'لا يوفّر سجل نقاط التكامل مسار تعديل معتمداً في هذه الوجهة. تبقى إجراءات البيانات الخاصة بكل اتصال في وجهاتها المصرّح بها.', 'draft', 'Endpoint edit-unavailable drawer reason'),
  ('admin.recordDrawer.package.editUnavailable', 'Your role doesn’t give you access to package authoring actions.', 'لا يتيح دورك إجراءات تأليف الحزم.', 'draft', 'Removed ''RLS-visible'' and ''governed'' jargon.'),
  ('admin.recordDrawer.roleStandard', 'Standard role', 'دور قياسي', 'draft', 'Role-class label; drops "governed"'),
  ('admin.reg.attachments.truth', 'Files are uploaded to private storage, checked with a checksum, and opened through short-lived signed links.', 'تُرفع الملفات إلى تخزين خاص، وتُفحص عبر مجموع تحقق، وتُفتح من خلال روابط موقعة قصيرة الأجل.', 'draft', 'Attachments footnote; dropped ''governed'''),
  ('admin.reg.audit.empty', 'No activity found for this record.', 'لم يُعثر على أي نشاط لهذا السجل.', 'draft', 'Audit empty state'),
  ('admin.reg.audit.error', 'The change history couldn''t load. Reload to retry — this does not mean the history is empty.', 'تعذّر تحميل سجل التغييرات. أعد التحميل للمحاولة مجدداً — هذا لا يعني أن السجل فارغ.', 'draft', 'Audit read error'),
  ('admin.reg.audit.heading', 'Change history', 'سجل التغييرات', 'draft', 'Per-record audit section heading'),
  ('admin.reg.audit.readonly', 'This history is only available to configuration writers; your read-only role is not granted that access.', 'هذا السجل متاح فقط لمن يملكون صلاحية الكتابة في التهيئة؛ دورك للعرض فقط لا يمنح هذا الوصول.', 'draft', 'Audit read restriction'),
  ('admin.reg.library.requestOnly', 'This library is for viewing and searching. To create or change something, start a Compliance Configuration Request. Approved past versions stay unchanged.', 'هذه المكتبة مخصصة للعرض والبحث. لإنشاء أو تعديل شيء، ابدأ طلب تهيئة الامتثال. وتظل الإصدارات السابقة المعتمدة دون تغيير.', 'draft', 'List-mode request-only note'),
  ('admin.reg.lineage.heading', 'Version history', 'سجل الإصدارات', 'draft', '''lineage'' -> ''history'' per glossary'),
  ('admin.reg.lineage.successor', 'replaces an earlier version', 'يحل محل إصدار سابق', 'draft', 'Version-history row tag; dropped ''governed successor'''),
  ('admin.reg.operationalTransition.truth', 'Lifecycle changes happen all at once and are logged. Turning this off also blocks future use of the items, violations, and penalties tied to it, while keeping past versions. Turning it back on does not turn those back on too.', 'تحدث تغييرات دورة الحياة دفعة واحدة ويتم تسجيلها. إيقاف اللائحة يمنع أيضاً الاستخدام المستقبلي للبنود والمخالفات والجزاءات المرتبطة بها، مع الحفاظ على الإصدارات السابقة. وإعادة التفعيل لا يعيد تفعيل تلك العناصر المرتبطة.', 'draft', 'Lifecycle transition footnote; removed ''atomic''/''cascades'''),
  ('admin.reg.r1.backToRegister', 'Back to list', 'العودة إلى القائمة', 'draft', 'Detail-mode back link'),
  ('admin.reg.r1.degraded.body', 'Nothing is shown as zero. The count is unknown, not empty. Your session and navigation still work.', 'لا يُعرض أي شيء كصفر. العدد غير معروف وليس فارغًا. تبقى جلستك والتنقل يعملان.', 'draft', 'Degraded-read banner body'),
  ('admin.reg.r1.degraded.chip', 'list not available', 'القائمة غير متاحة', 'draft', 'Header badge when the regulation read fails'),
  ('admin.reg.r1.degraded.title', 'The regulation list could not load.', 'تعذّر تحميل قائمة اللوائح.', 'draft', 'Degraded-read banner title'),
  ('admin.reg.r1.detail.actions.heading', 'Configuration', 'التهيئة', 'draft', 'Section heading; dropped ''Governed'''),
  ('admin.reg.r1.detail.auditNote', 'Changes to this regulation row are logged. Clauses added to this record are logged too (trg_audit_regulation_clauses).', 'تُسجَّل التغييرات على صف هذه اللائحة. وتُسجَّل أيضاً البنود المضافة إلى هذا السجل (trg_audit_regulation_clauses).', 'draft', 'Detail header note; removed banned term ''dossier'''),
  ('admin.reg.r1.detail.beyond', 'Whether this can be published depends on the clause-to-item mappings shown above. Checklist versions lock in the item snapshots at publication.', 'يعتمد نشر هذه اللائحة على ربط البنود بالعناصر الموضح أعلاه. تُثبّت إصدارات قائمة التفتيش لقطات العناصر عند النشر.', 'draft', 'Publish-dependency footnote; ''frozen package definition'' -> checklist version wording'),
  ('admin.reg.r1.detail.clauses.empty.body', 'This regulation has no clauses. Add the first clause below — the read worked, it is really empty.', 'لا تحتوي هذه اللائحة على بنود. أضف البند الأول أدناه — نجحت القراءة، وهي فارغة فعلاً.', 'draft', 'Clauses empty state'),
  ('admin.reg.r1.detail.validation.noClauses', 'Blocked: at least one clause is needed.', 'محظور: يلزم بند واحد على الأقل.', 'draft', 'Publish blocker'),
  ('admin.reg.r1.detail.validation.ready', 'Every clause has at least one mapped inspection item. Approval and publication still happen through the request workflow.', 'يحتوي كل بند على عنصر تفتيش واحد مرتبط على الأقل. لا تزال الموافقة والنشر تتمان عبر مسار الطلب.', 'draft', 'Publish-ready confirmation'),
  ('admin.reg.r1.detail.validation.title', 'Ready to publish?', 'هل هي جاهزة للنشر؟', 'draft', 'Publish-readiness status label'),
  ('admin.reg.r1.empty.body', 'The read worked — the library is really empty (MVP1-M09-001: regulations are the parents of inspection items).', 'نجحت القراءة — المكتبة فارغة فعلاً (MVP1-M09-001: اللوائح هي الأصل لعناصر التفتيش).', 'draft', 'Empty catalogue body for readers'),
  ('admin.reg.r1.empty.body.writer', 'The read worked — the library is really empty. Create the first configuration through a Compliance Configuration Request.', 'نجحت القراءة — المكتبة فارغة فعلاً. أنشئ أول تهيئة من خلال طلب تهيئة الامتثال.', 'draft', 'Empty catalogue body for writers'),
  ('admin.reg.r1.empty.title', 'No regulations set up yet', 'لا توجد لوائح بعد', 'draft', 'Empty catalogue title'),
  ('admin.reg.r1.filteredEmpty.body', 'The list itself is not empty. Clear the search or lifecycle filter.', 'القائمة نفسها ليست فارغة. امسح البحث أو عامل تصفية دورة الحياة.', 'draft', 'Filtered-empty state body on regulation list'),
  ('admin.reg.r1.loading', 'Loading regulation list…', 'جارٍ تحميل قائمة اللوائح…', 'draft', 'Loading skeleton sr-only label; ''register'' -> ''list'''),
  ('admin.reg.r1.openDossier', 'View record', 'عرض السجل', 'draft', 'Regulation list row action to open the detail view (glossary: elsewhere-context noun, not Factory profile)'),
  ('admin.reg.r1.readonly.body', 'You can view settings here. To create, add clauses, or publish, you need a Compliance or Form Admin role. This is enforced by row-level security. The route guard and database permissions are separate controls.', 'يمكنك عرض الإعدادات هنا. للإنشاء أو إضافة بنود أو النشر، تحتاج دور مسؤول الامتثال أو مسؤول النماذج. يُفرض ذلك عبر أمان مستوى الصف. حارس المسار وصلاحيات قاعدة البيانات ضوابط منفصلة.', 'draft', 'Read-only role banner'),
  ('admin.reg.r1.title', 'Inspection Rules — regulation list', 'قواعد التفتيش — قائمة اللوائح', 'draft', 'Page title; Compliance Library renamed to Inspection Rules'),
  ('admin.reg.requestOnly.body', 'To create or change clauses, attachments, release dates, or new versions, you must submit a Compliance Configuration Request. The current approved version stays available until that request is approved and published.', 'لإنشاء أو تعديل البنود أو المرفقات أو تواريخ الإصدار أو الإصدارات الجديدة، يجب تقديم طلب تهيئة الامتثال. ويظل الإصدار المعتمد الحالي متاحاً حتى اعتماد الطلب ونشره.', 'draft', 'Request-controlled-content note (detail + list mode)'),
  ('admin.revamp.access.gate.body', 'Every write is checked again on the server. Approved RPCs refuse self-elevation and removal of the last security administrator; backend role keys stay unchanged until an approved mapping migration exists.', 'يُعاد التحقق من صلاحية كل كتابة على الخادم. ترفض إجراءات قاعدة البيانات المعتمدة رفع المستخدم لصلاحياته أو إزالة آخر مسؤول أمان؛ وتبقى مفاتيح الأدوار الخلفية دون تغيير إلى أن تُعتمد ترحيلة للربط.', 'draft', 'Access gate copy'),
  ('admin.revamp.access.metric.roles', 'Role keys', 'مفاتيح الأدوار', 'draft', 'Metric label; drops "Governed"'),
  ('admin.revamp.access.metric.users.note', 'Only profiles you can see', 'الملفات المرئية لك فقط', 'draft', 'Accounts-in-scope metric note'),
  ('admin.revamp.access.note', 'The design''s three presentation roles sit above the existing approved role catalogue. This route does not collapse or rename backend roles without an approved data and RLS migration.', 'توجد أدوار العرض الثلاثة في التصميم فوق كتالوج الأدوار المعتمد الحالي. لا تدمج هذه الوجهة أدوار النظام الخلفي ولا تعيد تسميتها دون ترحيلة معتمدة للبيانات وأمن الصفوف.', 'draft', 'Access reconstruction note'),
  ('admin.revamp.integration.governance.degrade', 'Providers that aren''t available are blocked safely, and features that depend on them show this limit.', 'الجهات المزودة غير المتاحة تُمنع بأمان، وتوضح الميزات المعتمدة عليها هذا الحد.', 'draft', 'Integration governance bullet; drops fail-closed jargon'),
  ('admin.revamp.integration.governance.secrets', 'Secrets are never shown; only the approved contract and runtime state are shown.', 'لا تُعرض الأسرار؛ ويُعرض فقط العقد المعتمد وحالة التشغيل.', 'draft', 'Integration governance bullet'),
  ('admin.revamp.integration.governance.truth', 'Configuration, connectivity and delivery are different truth states.', 'الإعداد والاتصال والتسليم حالات حقيقة منفصلة.', 'draft', 'Integration governance bullet'),
  ('admin.revamp.integration.metric.registered.note', 'Read from the endpoint registry', 'مقروءة من سجل نقاط التكامل', 'draft', 'Registered-endpoints metric note'),
  ('admin.revamp.integration.note', 'Prototype provider names, sync times and health labels are not copied. The register, event stream and export jobs below are backend reads limited to what you''re allowed to see; missing tables or rows show as not available or as a checked, empty state.', 'لا تُنسخ أسماء الجهات المزودة أو أوقات المزامنة أو تسميات الصحة النموذجية. سجل التكامل وتدفق الأحداث ومهام التصدير أدناه قراءات خلفية تقتصر على ما يُسمح لك برؤيته؛ وتظهر الجداول أو الصفوف المفقودة كحالة غير متاحة أو حالة فارغة تم التحقق منها.', 'draft', 'Integrations reconstruction note'),
  ('admin.revamp.integration.title', 'System Connections', 'اتصالات النظام', 'draft', 'Regression fix: glossary Integration Management -> System Connections'),
  ('admin.revamp.lookup.metric.total.note', 'A key-ordered registry, showing only what you can see', 'سجل مرتب بالمفتاح، يعرض فقط ما يُسمح لك برؤيته', 'draft', 'Reference Lists metric note'),
  ('admin.revamp.lookup.note', 'The canonical Lookup destination resolves to the existing localization and approved planning-lookup sources. No reference-list count or language completeness claim is made up.', 'تتجه وجهة القوائم المرجعية إلى مصادر الترجمة وقوائم التخطيط المعتمدة الحالية. لا يتم اختلاق عدد للقوائم أو ادعاء اكتمال اللغة.', 'draft', 'Reference Lists reconstruction note'),
  ('admin.revamp.lookup.title', 'Reference Lists', 'القوائم المرجعية', 'draft', 'Regression fix: glossary Lookup Management -> Reference Lists'),
  ('admin.revamp.risk.gate.body', 'MVP1 engine settings take effect only through the existing risk-owner action, after validation and confirmation. Model drafts use a separate maker-checker route. This screen does not treat the two as one.', 'لا تصبح إعدادات محرك MVP1 نافذة إلا عبر إجراء مالك المخاطر الحالي بعد التحقق والتأكيد. تستخدم مسودات النماذج مساراً منفصلاً لفصل المُعدّ عن المعتمد. لا تعامل هذه الشاشة العقدين كعقد واحد.', 'draft', 'Risk gate copy'),
  ('admin.revamp.risk.governance.trace', 'Scores can always be reproduced from the stored inputs and the settings version.', 'يمكن دائماً إعادة إنتاج الدرجات من المدخلات المخزنة وإصدار الإعدادات.', 'draft', 'Risk drawer governance bullet'),
  ('admin.revamp.risk.metric.version', 'Settings version', 'إصدار الإعدادات', 'draft', 'Risk Studio metric label'),
  ('admin.revamp.risk.title', 'Risk Settings', 'إعدادات المخاطر', 'draft', 'Regression fix: glossary Risk Configuration -> Risk Settings'),
  ('admin.revamp.survey.gate.body', 'A package used by a published visit can’t have its structure edited. Changes create a new draft instead. Existing and past inspections stay pinned to their original package version.', 'لا يمكن تعديل بنية حزمة تستخدمها زيارة منشورة. تُنشئ التغييرات مسودة جديدة بدلاً من ذلك، وتبقى عمليات التفتيش الحالية والسابقة مرتبطة بإصدار الحزمة الأصلي.', 'draft', 'Split into shorter sentences; ''historical'' -> ''past''.'),
  ('admin.revamp.survey.gate.title', 'Published packages can’t be changed', 'الحزم المنشورة غير قابلة للتغيير', 'draft', 'immutable -> plain phrasing; Arabic already read this way, unchanged.'),
  ('admin.revamp.survey.metric.items.note', 'Items you can see', 'البنود التي يمكنك الاطلاع عليها', 'draft', 'Removed ''RLS-visible governed'' jargon from a metric caption.'),
  ('admin.revamp.survey.note', 'The design’s sample package names, counts and rule contents are not copied. This workspace shows the real package, item, template, impact and locked-version data already used by execution.', 'لا تُنسخ أسماء حزم التصميم النموذجية أو أعدادها أو محتوى قواعدها. تعرض مساحة العمل هذه مصادر الحزم والبنود والقوالب والأثر والإصدارات غير القابلة للتغيير التي يستخدمها التنفيذ فعلياً.', 'draft', '''renders''->''shows'', ''immutable-version''->''locked-version''; Arabic unchanged (already plain).'),
  ('admin.revamp.survey.title', 'Inspection Forms', 'نماذج التفتيش', 'draft', 'Glossary: Survey Configuration -> Inspection Forms (exact named admin module).'),
  ('admin.risk.banner.after', '— scores must be able to be reproduced from stored inputs plus this version (EV-004). Only the risk_owner role can write; everyone else is blocked. Every save is recorded in the Activity Log, which can''t be changed.', '— يجب أن يكون بالإمكان إعادة إنتاج الدرجات من المدخلات المخزنة زائد هذا الإصدار (EV-004). فقط دور مالك المخاطر يمكنه الكتابة؛ يُمنع الجميع سواه. يُسجَّل كل حفظ في سجل النشاط، ولا يمكن تغييره.', 'draft', 'Risk Studio banner (after engine_settings code tag); glossary Audit Trail -> Activity Log applied'),
  ('admin.risk.banner.before', 'Weights and bands are live settings in', 'الأوزان والنطاقات إعدادات فعّالة في', 'draft', 'Risk Studio banner (before engine_settings code tag)'),
  ('admin.risk.banner.title', 'This is the Risk Studio (MVP1 starting scope).', 'هذا استوديو المخاطر (نطاق التأسيس لـ MVP1).', 'draft', 'Risk Studio banner title'),
  ('admin.risk.confirmLive', 'I understand this setting takes effect right away for new score calculations.', 'أفهم أن هذا الإعداد يسري فوراً على حسابات الدرجات الجديدة.', 'draft', 'Risk Studio live-write confirmation checkbox'),
  ('admin.risk.empty.desc', 'No risk settings exist in your allowed scope. Create one through the approved setup process before using this studio.', 'لا توجد إعدادات مخاطر ضمن نطاقك المسموح به. أنشئ واحدة عبر عملية الإعداد المعتمدة قبل استخدام هذا الاستوديو.', 'draft', 'Risk Studio empty state'),
  ('admin.risk.error.body', 'We couldn’t verify the existing settings. Nothing changed; retry or check your risk-owner access.', 'تعذّر التحقق من الإعدادات الحالية. لم يتغيّر شيء؛ أعد المحاولة أو تحقق من صلاحية مالك المخاطر لديك.', 'draft', 'Risk Studio load error body'),
  ('admin.risk.error.title', 'Couldn’t load risk settings.', 'تعذّر تحميل إعدادات المخاطر.', 'draft', 'Risk Studio load error'),
  ('admin.risk.nav.label', 'Risk settings', 'إعدادات المخاطر', 'draft', 'Risk section nav label'),
  ('admin.risk.nav.models', 'Model versions', 'إصدارات النماذج', 'draft', 'Risk Studio tabs; was "Governed models"'),
  ('admin.risk.save', 'Save settings (risk_owner only)', 'حفظ الإعدادات (لمالك المخاطر فقط)', 'draft', 'Risk Studio save button'),
  ('admin.risk.saved', 'saved — takes effect right away', 'تم الحفظ — يسري فوراً', 'draft', 'Risk Studio save toast'),
  ('admin.risk.savedNote', 'Saving writes factors and bands to engine_settings after the weights-sum check. It takes effect right away for new score calculations — there is no draft or approval step on this screen.', 'يكتب الحفظ العوامل والنطاقات إلى engine_settings بعد التحقق من مجموع الأوزان. يسري ذلك فوراً على حسابات الدرجات الجديدة — لا توجد خطوة مسودة أو موافقة في هذه الشاشة.', 'draft', 'Risk Studio save helper text'),
  ('admin.senai.endpoints.blocked', 'forwarding is turned off; nothing is sent', 'إعادة التوجيه معطّلة؛ لا يُرسَل شيء', 'draft', 'Endpoints tab governance-block note'),
  ('admin.senai.endpoints.callsError', 'Recorded live calls could not be read. The endpoint allow-list stays visible, but live-call verification is not available — not unverified.', 'تعذّرت قراءة الاستدعاءات الفعلية المسجلة. تبقى قائمة نقاط الاتصال المسموحة مرئية، لكن التحقق من الاستدعاء الفعلي غير متاح — لا يعني ذلك عدم التحقق.', 'draft', 'Endpoints tab error'),
  ('admin.senai.endpoints.caption', 'SENAI endpoint contract and recorded call verification', 'عقد نقاط اتصال SENAI والتحقق من الاستدعاءات المسجلة', 'draft', 'Endpoints table caption'),
  ('admin.senai.endpoints.footer', 'Verification comes only from recorded senaei_sync_calls rows. A non-success response shows the dependent Factory 360 section as honestly “not available right now” — never a made-up value. Endpoints outside this contract are refused by the client before any request leaves the server.', 'يأتي التحقق فقط من صفوف senaei_sync_calls المسجلة. عند استجابة غير ناجحة، يظهر قسم Factory 360 المعتمد على ذلك بصدق كـ«غير متاح الآن» — وليس بقيمة مختلقة. تُرفض نقاط الاتصال خارج هذا العقد من قبل العميل قبل مغادرة أي طلب للخادم.', 'draft', 'Endpoints tab footer; simple-English fix temporarily->"right now"'),
  ('admin.senai.endpoints.verificationUnavailableShort', 'Live-call verification not available', 'التحقق من الاستدعاء الفعلي غير متاح', 'draft', 'Endpoints tab badge'),
  ('admin.senai.fnd007.breach', 'breach: the endpoint contract now has a master-data write endpoint. Stop and escalate.', 'خرق: عقد نقطة الاتصال يحتوي الآن على نقطة كتابة للبيانات الأساسية. توقف وصعّد الأمر.', 'draft', 'FND-007 write-back status'),
  ('admin.senai.fnd007.derived', 'holds: the endpoint contract has no establishment master-data write-back.', 'صامد: عقد نقطة الاتصال لا يحتوي على كتابة عكسية لبيانات المنشأة الأساسية.', 'draft', 'FND-007 write-back status'),
  ('admin.senai.kpi.sourceUnavailable', 'Run source not available / Source registry not available', 'مصدر التشغيل غير متاح / سجل المصدر غير متاح', 'draft', 'Reconcile KPI deltas (same key, two fallback texts as in original source)'),
  ('admin.senai.mapping.body', 'No field-mapping registry exists in the applied schema, so no mapping rule can be shown. You must not invent SENAI-to-internal field mappings, transforms or enum maps here: they change how source data is understood later. Until a mapping registry is approved and applied, the adapters in lib/integrations/senaei/adapters stay the only source for mapping, and unmapped fields show up later as “not configured”.', 'لا يوجد سجل ربط حقول في المخطط المطبَّق، لذا لا يمكن عرض أي قاعدة ربط. يجب عدم اختلاق روابط حقول من SENAI إلى الحقول الداخلية أو التحويلات أو خرائط التعداد هنا: فهي تغيّر كيفية فهم بيانات المصدر لاحقاً. إلى أن يُعتمد سجل ربط ويُطبَّق، تبقى المحولات في lib/integrations/senaei/adapters المصدر الوحيد للربط، وتظهر الحقول غير المربوطة لاحقاً كـ«غير مُهيّأ».', 'draft', 'Field mapping tab body'),
  ('admin.senai.recon.connectionsError', 'Source connections could not be read. The source-validation count is not available; recorded run and divergence facts are preserved.', 'تعذّرت قراءة اتصالات المصدر. عدد التحقق من المصدر غير متاح؛ تُحفظ حقائق التشغيل والاختلافات المسجلة.', 'draft', 'Reconcile tab error'),
  ('admin.senai.recon.empty', 'No unresolved divergence is recorded. This is a checked, empty result.', 'لا يوجد اختلاف غير محلول مسجل. هذه نتيجة فارغة تم التحقق منها.', 'draft', 'Reconcile table empty state'),
  ('admin.senai.recon.error', 'Reconciliation divergences could not be read. This is data that''s not available, not a checked, empty divergence set.', 'تعذّرت قراءة اختلافات المطابقة. هذه بيانات غير متاحة، وليست مجموعة اختلافات فارغة تم التحقق منها.', 'draft', 'Reconcile tab error'),
  ('admin.senai.recon.footer', 'Resolution is an approved reconciliation action, not an edit on this screen. SAQEEL never silently overwrites a divergence in either direction, and never writes the resolution back to SENAI.', 'الحل إجراء مطابقة معتمد، وليس تعديلاً في هذه الشاشة. لا تستبدل SAQEEL أي اختلاف بصمت في أي اتجاه، ولا تكتب الحل مرة أخرى إلى SENAI.', 'draft', 'Reconcile tab footer'),
  ('admin.senai.recon.runsError', 'Sync runs could not be read. Total row counts and freshness are not available; reconciliation divergences below remain independent.', 'تعذّرت قراءة عمليات المزامنة. إجمالي عدد الصفوف والحداثة غير متاحين؛ تبقى الاختلافات في المطابقة أدناه مستقلة.', 'draft', 'Reconcile tab error'),
  ('admin.senai.sources.empty', 'No source connection is registered. This is a checked, empty result, not a failure.', 'لا يوجد اتصال مصدر مسجل. هذه نتيجة فارغة تم التحقق منها، وليست فشلاً.', 'draft', 'Sources table empty state'),
  ('admin.senai.sources.footerUnavailable', 'Run freshness and counts are not available because the run source failed. Connection facts above remain readable.', 'حداثة عمليات التشغيل وأعدادها غير متاحة لأن مصدر التشغيل فشل. تبقى حقائق الاتصال أعلاه قابلة للقراءة.', 'draft', 'Sources tab footer'),
  ('admin.senai.sources.help', 'Source data is read-only; this registry records which connections SAQEEL uses. Setting it up is not the same as being connected.', 'بيانات المصدر للقراءة فقط؛ يسجل هذا السجل الاتصالات التي يستخدمها SAQEEL. إعداد الشيء لا يعني أنه متصل.', 'draft', 'Sources tab helper'),
  ('admin.senai.sources.runsError', 'Recorded runs could not be read. Available connection settings are kept without a guessed freshness or counts.', 'تعذّرت قراءة عمليات التشغيل المسجلة. تُحفظ إعدادات الاتصال المتاحة دون تخمين للحداثة أو الأعداد.', 'draft', 'Sources tab error'),
  ('admin.senai.unavailable', 'Not available', 'غير متاح', 'draft', 'Reused badge/value fallback across Sources/Endpoints/Reconcile tabs'),
  ('admin.template.historical', 'Locked historical template version.', 'إصدار قالب سابق مقفل.', 'draft', 'immutable -> locked.'),
  ('admin.template.intro', 'Create versioned, bilingual templates for forms, reports, action forms, or penalties. Published versions can’t be changed, and can be used by package action forms and penalty mappings.', 'أنشئ قوالب مرقّمة بالإصدار وثنائية اللغة للنماذج والتقارير ونماذج الإجراءات أو العقوبات. لا يمكن تغيير الإصدارات المنشورة، ويمكن استخدامها في نماذج إجراءات الحزم وربط العقوبات.', 'draft', 'immutable -> can''t be changed.'),
  ('admin.templates.empty.body', 'Templates are versioned, bilingual objects used by packages and action forms.', 'القوالب كائنات مرقّمة بالإصدار وثنائية اللغة تستخدمها الحزم ونماذج الإجراءات.', 'draft', 'Dropped ''schema'' jargon word.'),
  ('admin.viol.audit.unavailable', 'Audit history couldn''t load — this doesn''t mean there are no events.', 'تعذّر تحميل سجل التدقيق — هذا لا يعني عدم وجود أحداث.', 'draft', 'Audit read failure'),
  ('admin.viol.audit.writerOnly', 'Audit history is only available to configuration writers.', 'سجل التدقيق متاح فقط لمن يملكون صلاحية الكتابة في التهيئة.', 'draft', 'Audit visibility restriction'),
  ('admin.viol.ccrRequired.body', 'Creating, changing, publishing, activating, and deactivating violations and penalties is read-only here for now. Use Compliance Configuration Requests instead — this catalogue will not skip that process.', 'إنشاء المخالفات والعقوبات وتعديلها ونشرها وتفعيلها وإلغاء تفعيلها للقراءة فقط هنا حالياً. استخدم طلبات تهيئة الامتثال بدلاً من ذلك — لن يتجاوز هذا الكتالوج تلك العملية.', 'draft', 'CCR-required banner; dropped ''workspace'' and ''atomic dependency cascade'''),
  ('admin.viol.lens.c3', 'Legal basis is present before create (never made up).', 'الأساس القانوني موجود قبل الإنشاء (لا يُختلق أبداً).', 'draft', 'Lens rule c3'),
  ('admin.viol.lens.c4', 'Range and repeat presets are fixed choices, not amounts.', 'الأنماط المسبقة للنطاق والتكرار خيارات ثابتة، وليست مبالغ.', 'draft', 'Mapping validation lens rule; dropped ''governed tokens'''),
  ('admin.viol.lens.intro', 'Creating a mapping checks legal basis, lifecycle, type, an optional amount, timing, repeat policy, and an optional template reference that can''t change later. No value is guessed or made up.', 'يتحقق إنشاء الربط من الأساس القانوني ودورة الحياة والنوع ومبلغ اختياري والتوقيت وسياسة التكرار ومرجع قالب اختياري لا يمكن تغييره لاحقاً. لا يُخمَّن أو يُختلق أي قيمة.', 'draft', 'Mapping Validation Lens intro; dropped ''immutable'''),
  ('admin.viol.map.template', 'Template', 'القالب', 'draft', 'Form field label; dropped ''Governed'''),
  ('admin.viol.penalty.footer', 'One violation = one penalty — the database rejects a second mapping. Presets are fixed choices, never money amounts or legal values.', 'مخالفة واحدة = عقوبة واحدة — ترفض قاعدة البيانات ربطاً ثانياً. الأنماط المسبقة خيارات ثابتة، وليست مبالغ مالية أو قيماً قانونية أبداً.', 'draft', 'Penalty-mapping footer; dropped contract-route mention'),
  ('admin.viol.readonly', 'Read-only view. To make changes you need the compliance-admin or form-admin role. Being able to see this page does not give you write access.', 'عرض للقراءة فقط. لإجراء تغييرات تحتاج دور مسؤول الامتثال أو مسؤول النماذج. رؤية هذه الصفحة لا تمنحك صلاحية الكتابة.', 'draft', 'Read-only role banner; removed ''(RLS)'''),
  ('admin.viol.usage.unavailable', 'Usage couldn''t load — this doesn''t mean the count is zero.', 'تعذّر تحميل بيانات الاستخدام — هذا لا يعني أن العدد صفر.', 'draft', 'Usage read failure'),
  ('admin.viol.usage.writerOnly', 'Usage counts are only available to configuration writers.', 'أعداد الاستخدام متاحة فقط لمن يملكون صلاحية الكتابة في التهيئة.', 'draft', 'Usage visibility restriction'),
  ('admin.wf.banner.after', 'and can''t be edited here.', 'ولا يمكن تعديلها هنا.', 'draft', 'Workflow Settings banner (after engine_settings code tag)'),
  ('admin.wf.banner.before', 'The system checks transitions against the published version only — no status bypass (RBAC-003). Changes go from draft to publish, and the approver must be a different person (RBAC-002 maker-checker), enforced by a database rule on', 'يتحقق النظام من الانتقالات مقارنةً بالإصدار المنشور فقط — بلا تجاوز للحالة (RBAC-003). تنتقل التغييرات من مسودة إلى نشر، ويجب أن يكون المعتمِد شخصاً مختلفاً (آلية المُعدّ/المعتمد RBAC-002)، وتُفرض هذه القاعدة عبر قاعدة بيانات على', 'draft', 'Workflow Settings banner (before config_versions code tag)'),
  ('admin.wf.banner.mid', '); published versions can''t be changed. Risk/SLA values live in', ')؛ لا يمكن تغيير الإصدارات المنشورة. تعيش قيم المخاطر/SLA في', 'draft', 'Workflow Settings banner (mid)'),
  ('admin.wf.banner.title', 'Only approved changes.', 'التغييرات المعتمدة فقط.', 'draft', 'Workflow Settings banner'),
  ('admin.wf.chain.pending', 'awaiting a distinct approver (maker-checker, enforced by the database)', 'بانتظار معتمِد مختلف (آلية المُعدّ/المعتمد، تفرضها قاعدة البيانات)', 'draft', 'Workflow approval chain pending state'),
  ('admin.wf.crumb.leaf', 'Lifecycles', 'دورات الحياة', 'draft', 'Workflow Settings breadcrumb; was "Governed lifecycles"'),
  ('admin.wf.empty.body', 'Workflow state machines are versioned settings (ENG-03).', 'آلات حالة سير العمل هي إعدادات ذات إصدارات (ENG-03).', 'draft', 'Workflow empty state body'),
  ('admin.wf.empty.title', 'No workflow settings published', 'لا توجد إعدادات سير عمل منشورة', 'draft', 'Workflow empty state'),
  ('admin.wf.error.title', 'Couldn’t load workflow settings. Nothing was changed. Try again.', 'تعذّر تحميل إعدادات سير العمل. لم يتغيّر شيء. حاول مرة أخرى.', 'draft', 'Workflow load error'),
  ('admin.wf.sla.authorized', 'Approved', 'معتمد', 'draft', 'SLA calendar activation badge'),
  ('admin.wf.sla.none', 'No SLA calendar is set up. Deadlines, working days and escalation are set inputs (DEC-003) — until one is approved, timers stay pending and no deadline is shown.', 'لا يوجد تقويم SLA مُعدّ. المواعيد النهائية وأيام العمل والتصعيد مدخلات محددة (DEC-003) — إلى أن تُعتمد إحداها تبقى المؤقتات معلّقة ولا يظهر موعد نهائي.', 'draft', 'SLA model empty state'),
  ('admin.wf.sla.note', 'Deadlines are computed only from an approved working calendar. There is no scheduler: a breach is never triggered on its own, and no default duration is assumed.', 'تُحسب المواعيد النهائية فقط من تقويم عمل معتمد. لا يوجد مجدوِل: لا يُطلَق أي خرق للموعد تلقائياً، ولا تُفترض أي مدة افتراضية.', 'draft', 'SLA model footer note'),
  ('admin.wf.sla.pending', 'Not approved (DEC-003)', 'غير معتمد (DEC-003)', 'draft', 'SLA calendar activation badge'),
  ('admin.wf.sod.desc', 'You proposed this draft (the maker). A different checker must approve it — the database enforces this separation of duties.', 'أنت اقترحت هذه المسودة (المُعدّ). يجب أن يعتمدها شخص مختلف (المعتمِد) — قاعدة البيانات تفرض هذا الفصل بين المهام.', 'draft', 'Workflow separation-of-duties tooltip'),
  ('cmte.banner.body', 'Signature and refusal are distinct facts; queued is not delivered. Verification is never "verified" without a provider — PKI/EBDA is on hold. Acknowledgement is not a signature.', '(authored in ui_strings DB, not this file)', 'draft', '''held'' -> ''on hold'' for consistency'),
  ('cmte.empty.title / cmte.empty.body', 'No signature or verification records to show / Records appear here as reports are signed and verifications are requested. If this is empty, it may also mean none are visible to your role.', '(authored in ui_strings DB, not this file)', 'draft', 'Removed literal ''(RLS)'' jargon from visible empty-state copy'),
  ('cmte.off', 'The committee decision record is not turned on here. PKI/EBDA verification is on hold.', '(authored in ui_strings DB, not this file)', 'draft', 'dossier -> record (committee-object exception); enabled/held simplified'),
  ('common.action (col header)', 'Action', 'إجراء', 'draft', 'Error-queue table column header; drops "Governed action"'),
  ('common.action (devices col header)', 'Command', 'أمر', 'draft', 'Devices table column header; drops "Governed command"'),
  ('common.unavailable', 'Not available', 'غير متاح', 'draft', 'Reused KPI fallback (also touched in access/page.tsx)'),
  ('common.unavailable (devices badge)', 'Not available', 'غير متاح', 'draft', 'Trusted-device count fallback'),
  ('common.unavailable (roleKeys cell)', 'Not available', 'غير متاح', 'draft', 'User-roles table cell when roles failed to load'),
  ('common.unavailable (roleValue)', 'Not available', 'غير متاح', 'draft', 'Role column fallback when roles failed to load'),
  ('exc.banner.body', 'This board shows real cases and risk exceptions. Decisions stay on the original record. Every count matches its source — nothing here is made up.', 'تعرض هذه اللوحة الحالات الفعلية واستثناءات المخاطر. تبقى القرارات على السجل الأصلي. كل عدد يطابق مصدره — لا شيء هنا مُختلَق.', 'draft', 'Banner body. Was ''Exceptions are a projection over real objects — decisions stay on the owning object. Counts trace 1:1 to sources (no synthetic rows).'' — this was raw engineering-projection jargon in a user-facing banner.'),
  ('exc.banner.title', 'Live status.', 'الحالة المباشرة.', 'draft', 'Banner strong-text lead-in. Was ''Command posture.'' — dev/ops jargon with no clear meaning to an end user.'),
  ('exc.empty.body', 'Open cases and risk exceptions show up here. If this is empty, it may also mean there are none you''re allowed to see.', 'تظهر هنا الحالات المفتوحة واستثناءات المخاطر. إذا كانت هذه القائمة فارغة، فقد يعني ذلك أيضًا عدم وجود ما يمكنك رؤيته.', 'draft', 'Was ''Open cases and risk exceptions surface here. Empty may also mean none are in your scope (RLS).'' — raw ''(RLS)'' was directly user-visible.'),
  ('exc.empty.title', 'No open exceptions you can see', 'لا توجد استثناءات مفتوحة يمكنك رؤيتها', 'draft', 'Was ''No open exceptions in scope''.'),
  ('exc.off', 'This board is not turned on here.', 'هذه اللوحة غير مفعّلة هنا.', 'draft', 'NotYetBoundary consequence copy for the feature-flagged exception board. Was ''The operations exception board is not enabled here.'''),
  ('f360.actions.planSingle', 'Plan one visit', 'تخطيط زيارة واحدة', 'draft', 'Action button on the legacy factory page and the field Factory 360 sticky action bar, was ''Plan single visit'' — glossary: single visit -> Plan one visit.'),
  ('f360.compliance.rule', 'Calculated only from the latest final submitted version of approved inspections and the checklist version used for the inspection. Returned or rejected inspections stay visible below, but they never affect this rate.', 'يُحتسب فقط من أحدث نسخة نهائية مرسلة من التفتيشات المعتمدة ونسخة قائمة التحقق المستخدمة في التفتيش. تظل التفتيشات المعادة أو المرفوضة ظاهرة أدناه، لكنها لا تؤثر في هذه النسبة.', 'draft', 'Compliance-rate caption. ''immutable submitted version'' -> ''final submitted version'' and ''frozen package definition'' -> ''checklist version used for the inspection'' per glossary.'),
  ('f360.empty.title', 'No factories in the list (unchanged EN, already correct)', 'لا توجد مصانع في القائمة', 'draft', 'Empty-state title on /factories. EN already said ''list'' but AR fallback still said ''السجل'' (registry) — Arabic-only drift, fixed to match.'),
  ('f360.hist.th.operational', 'Visit status', '(no existing arabic.ts entry for this key — none added, out of touched-entries scope)', 'draft', 'Inspection-history table column header, was ''Operational''.'),
  ('f360.list.dossier', 'View factory (unchanged EN, already correct)', 'عرض المصنع', 'draft', 'Factory-list row action. EN was already fixed to ''View factory'' in an earlier wave but the AR fallback had drifted to ''عرض ملف المصنع'' (View factory profile), which conflates the row-action wording with the destination-page wording. Trimmed AR to match EN exactly.'),
  ('f360.list.portfolio', 'Choose a factory', 'اختيار مصنع', 'draft', 'Factory-list scope picker: aria-label of the CR-select form + its visible <label> text. Was ''Factory portfolio'' (regression); the dropdown selects which factory/CR to view, so ''All licenses'' (the literal glossary mapping for ''portfolio'') didn''t fit the actual UI function — used plain simple-English instead.'),
  ('f360.observed.rule', 'The observed column shows the official record as it was when someone submitted a report that was later approved. It does not change the current official record.', 'يعرض عمود الرصد البيانات الرسمية كما كانت عند إرسال تقرير أصبح معتمداً لاحقاً. ولا يغيّر البيانات الرسمية الحالية.', 'draft', 'Caption under the official-vs-observed comparison table. Dropped ''immutable'', ''hierarchy'', ''overwrite ... source truth'' jargon for plain short sentences.'),
  ('f360.report.version', 'Latest final version', 'أحدث نسخة نهائية', 'draft', 'Inspection-reports table column header, was ''Latest immutable version''.'),
  ('f360.tl.operational', 'visit status', '(no existing arabic.ts entry for this key)', 'draft', 'Inline label prefix in the Spatial Case Timeline card (''planning X · visit status Y''), was ''operational''.'),
  ('f360.visits.operationalStatus', 'Visit status', 'حالة الزيارة', 'draft', 'Visit-summary table column header, was ''Operational status'' — glossary: operational (column) -> Visit status. Inline bilingual() call, both EN and AR updated together.'),
  ('f360.xpc.package', 'Checklist version / submission version', 'نسخة قائمة التحقق / نسخة الإرسال', 'draft', 'Cross-provider reconciliation fact label, was ''Approved package / submission version'' — glossary: frozen package definition -> checklist version used for the inspection.'),
  ('f360.xpc.rule', 'Facts are checked once, by the system. Industry Shared master data is not verified yet, so it is not used. Inspection API values give context. Approved report facts are the most reliable. If facts conflict, we show the conflict — we never hide or overwrite it.', 'تُفحص البيانات مرة واحدة بواسطة النظام. بيانات Industry Shared الرئيسية غير محقّقة بعد، لذلك لا تُستخدم؛ قيم واجهة التفتيش سياقية؛ وبيانات التقارير المعتمدة هي الأكثر موثوقية. عند وجود تعارض في البيانات، نعرضه ولا نخفيه أو نكتب فوقه أبداً.', 'draft', 'Source-reconciliation rule caption. Removed ''server-side'', ''contract-unverified (fail-closed)'' dev jargon; the field/factory-360/[id]/page.tsx copy of this key already had different (already-cleaned) text and was left as-is since it wasn''t a grep hit.'),
  ('field.fv.categoryPending', 'This category is not connected yet — there is no data source yet.', 'هذه الفئة غير مرتبطة بعد — لا يوجد مصدر بيانات بعد.', 'draft', 'Pending-integration category caption'),
  ('field.fv.pendingCaption', 'This section is a placeholder until a data source is connected — anything entered here is not saved yet.', 'هذا القسم عنصر نائب حتى يتم ربط مصدر بيانات — أي قيمة تُدخل هنا لا تُحفظ بعد.', 'draft', 'Factory-360 pending-integration caption; dropped ''governed source'''),
  ('field.fv.unavailable', 'data source not available', 'مصدر البيانات غير متاح', 'draft', 'Interpolated into field.fv.loadError'),
  ('field.fv.violationHistoryPending', 'No violation history source yet.', 'لا يوجد مصدر لسجل المخالفات بعد.', 'draft', 'Violation-history empty scaffold caption'),
  ('field.ws.aiExplain.unavailable', 'AI explanation not available', 'شرح الذكاء الاصطناعي غير متاح', 'draft', 'AI-explain widget unavailable label'),
  ('field.ws.cancel.reasonsMissing', 'Cancellation reasons aren''t available right now.', 'أسباب الإلغاء غير متاحة الآن.', 'draft', 'Cancellation-request form; removed leaked ''engine_settings.field not seeded yet (0020 pending)'' internal detail'),
  ('field.ws.completionCreatedVersion', 'A final submitted version — you can''t edit it here anymore.', 'نسخة نهائية مُرسلة — لا يمكنك تعديلها هنا بعد الآن.', 'draft', 'Completion screen list of what the submission created'),
  ('field.ws.notConfigured', 'Inspection checklist not set up', 'قائمة التفتيش غير مُعدّة', 'draft', 'Empty state when the package_kind is unsupported (glossary: inspection package -> Inspection checklist)'),
  ('field.ws.notConfiguredDesc', 'This report type is not set up for field visits.', 'نوع هذا التقرير غير مُعدّ لزيارات الميدان.', 'draft', 'Body text alongside notConfigured'),
  ('field.ws.review.declaration', 'I confirm this inspection checklist is ready to submit.', 'أؤكد أن قائمة التفتيش هذه جاهزة للإرسال.', 'draft', 'Declaration checkbox label before final submit'),
  ('field.ws.review.hint', 'Review the whole inspection checklist before you create the final submitted version.', 'راجع قائمة التفتيش كاملةً قبل إنشاء النسخة النهائية المُرسلة.', 'draft', 'Final-review step hint (glossary: inspection package -> Inspection checklist, immutable submitted version -> final submitted version)'),
  ('field.ws.vio.penaltyConflict', 'Penalty mapping not available — settings conflict', 'ربط الغرامة غير متاح — تعارض في الإعدادات', 'draft', 'Violation panel penalty-mapping conflict message'),
  ('gis.banner.body', 'These values are stamped on every geo event (the settings version is recorded with each check-in — EV-005). Official coordinates stay owned by GIS Admin; field observations never overwrite them (FND-007). Per-factory geofence radii (SB20) are edited on the map below.', 'تُطبع هذه القيم على كل حدث جغرافي (يُسجَّل إصدار الإعدادات مع كل تسجيل حضور — EV-005). تبقى الإحداثيات الرسمية مملوكة لإدارة GIS؛ ولا تستبدلها ملاحظات الحقل أبداً (FND-007). تُحرَّر أنصاف أقطار السياج الجغرافي لكل مصنع (SB20) على الخريطة أدناه.', 'draft', 'GIS Studio banner body'),
  ('gis.empty.body', 'The Factory list is empty — geofences appear here once factories are synced (FND-007).', 'قائمة المصانع فارغة — تظهر السياجات الجغرافية هنا بعد مزامنة المصانع (FND-007).', 'draft', 'GIS Studio empty state; regression fix registry -> Factory list'),
  ('gis.error.title', 'GIS data not available.', 'بيانات GIS غير متاحة.', 'draft', 'GIS Studio load error'),
  ('gis.select.body', 'Click any pin to see its official coordinates and set its geofence radius (SB20).', 'انقر أي دبوس لعرض إحداثياته الرسمية وتحديد نصف قطر السياج الجغرافي له (SB20).', 'draft', 'GIS pin-select helper text'),
  ('gis.sp.banner.body', 'The official factory pin stays owned by GIS admin (FND-007); these are extra working layers. Geofence and accuracy use the accepted engine_settings.gis values. Mapbox rendering is on hold.', 'يبقى دبوس المصنع الرسمي مملوكاً لإدارة GIS (FND-007)؛ وهذه طبقات عمل إضافية. يستخدم السياج الجغرافي والدقة قيم engine_settings.gis المقبولة. عرض Mapbox معلَّق.', 'draft', 'Spatial canvas banner'),
  ('gis.sp.empty.body', 'GIS layers and working factory locations appear here. Empty may also mean none are in your scope.', 'تظهر هنا طبقات GIS ومواقع المصانع العاملة. قد يعني الفراغ أيضاً عدم وجود أي منها ضمن نطاقك.', 'draft', 'Spatial canvas empty state'),
  ('labels.degraded (AuditReplayWorkspace en/ar map)', 'Semantic replay contracts aren''t applied in this environment. Generic events that can''t be changed stay visible, and they aren''t promoted to official facts.', 'عقود الإعادة الدلالية غير مطبقة في هذه البيئة. تبقى الأحداث العامة غير القابلة للتغيير مرئية ولا تُرقّى إلى حقائق رسمية.', 'draft', 'Semantic-degraded banner'),
  ('labels.dossier (AuditReplayWorkspace en/ar map)', 'Point-in-time snapshot', 'لقطة في لحظة', 'draft', 'BANNED-TERM fix: dossier -> snapshot (audit-replay context, per rule, not Factory profile)'),
  ('labels.partial (AuditReplayWorkspace en/ar map)', 'Results reflect only what you can currently read.', 'تعكس النتائج فقط ما يمكنك قراءته حاليًا.', 'draft', 'Partial-scope banner'),
  ('labels.partialHistory (AuditReplayWorkspace en/ar map)', 'PARTIAL HISTORY. The limited server read reached its safety cap. Reconstruction and completeness aren''t confirmed for this result.', 'سجل جزئي. بلغ الاستعلام المحدود حد الأمان؛ لا تُعتمد إعادة البناء أو نتيجة الاكتمال.', 'draft', 'History-truncated banner'),
  ('labels.policy (AuditReplayWorkspace en/ar map)', 'Operational view only. Export, reveal, redaction, retention, watermark, purge and legal-evidence claims are held by policy.', 'عرض تشغيلي فقط. التصدير والكشف والحجب والاحتفاظ والعلامة المائية والحذف والحجية القانونية معلّقة بالسياسة.', 'draft', 'Policy-held banner'),
  ('labels.portfolio (AuditReplayWorkspace en/ar map)', 'All cases in current scope', 'جميع الحالات ضمن النطاق الحالي', 'draft', 'Audit replay case-head fallback when no case selected; simplified from Latinate "portfolio"'),
  ('labels.selectCase (AuditReplayWorkspace en/ar map)', 'Select one case that isn''t truncated, with a published ontology. Viewing all cases, or a partial page of events, never satisfies case completeness.', 'اختر حالة واحدة غير مبتورة مع أنطولوجيا منشورة. لا تحقق أحداث جميع الحالات أو الصفحة الجزئية اكتمال الحالة.', 'draft', 'Completeness ledger selection prompt'),
  ('landing.feature.audit.desc', 'Every action is saved to an activity log that can''t be changed. Updates and deletes are blocked by the database, not just discouraged.', 'يُحفظ كل إجراء في سجل نشاط لا يمكن تغييره. تُمنع عمليات التعديل والحذف من قبل قاعدة البيانات، لا بمجرد الاتفاق.', 'draft', 'Audit Trail -> Activity Log glossary, immutable -> can''t be changed'),
  ('landing.feature.audit.title', 'Append-only activity log', 'سجل نشاط لا يُعدَّل', 'draft', 'Paired with audit.desc; Audit Trail -> Activity Log glossary'),
  ('landing.feature.decisions.title', 'Locked decisions', 'قرارات مقفلة', 'draft', 'Immutable decisions -> Locked decisions'),
  ('landing.feature.risk.desc', 'Risk weights set factory bands and planning priority. They come from settings, not code.', 'تحدد أوزان المخاطر فئات المصانع وأولوية التخطيط. تأتي من الإعدادات، لا من الكود.', 'draft', 'Dropped ''Governed''/''configuration'' jargon'),
  ('landing.feature.rls.desc', '54 database security rules control every read and write. The screen adds no trust of its own — every request is checked.', '54 قاعدة أمنية في قاعدة البيانات تتحكم في كل قراءة وكتابة. لا تضيف الشاشة أي ثقة من عندها — يُتحقق من كل طلب.', 'draft', 'Landing security feature card; removed ''Row-Level-Security''/''frozen matrix'' dev jargon'),
  ('landing.footer.line', 'Access depends on your role · every action is recorded · MIM Saqeel design system', 'الوصول يعتمد على دورك · يُسجَّل كل إجراء · نظام تصميم MIM سقيل', 'draft', 'Simplified role-scoped/audited'),
  ('landing.mock.kpiSla', 'on-time deadlines', 'الالتزام بالمواعيد', 'draft', 'Decorative landing KPI caption, SLA -> Deadline for ordinary users'),
  ('landing.persona.admin.desc', 'Regulation library, form designer, violation registry, risk studio — every engine checked with maker-checker.', 'مكتبة اللوائح، مصمم النماذج، سجل المخالفات، استوديو المخاطر — يتم التحقق من كل أداة بأسلوب فصل المُنشئ عن المعتمد.', 'draft', 'Landing admin persona description; dropped ''package'', simplified ''governed'''),
  ('landing.persona.inspector.desc', 'Works offline. Checklists, evidence, and check-in at the approved location — every answer is saved and never lost.', 'يعمل دون اتصال. قوائم التحقق، والأدلة، وتسجيل الدخول في الموقع المعتمد — يُحفظ كل جواب ولا يُفقد أبداً.', 'draft', 'Landing inspector persona description; geofenced -> approved location (inspector-facing exception)'),
  ('landing.persona.portal.desc', 'Plan multiple visits, plan one visit, or create an urgent visit. Level 2 review decisions are locked once made, with an exact list of what needs to be redone.', 'خطط زيارات متعددة، أو زيارة واحدة، أو أنشئ زيارة عاجلة. تُقفل قرارات مراجعة المستوى الثاني فور اتخاذها، مع قائمة دقيقة بما يجب إعادته.', 'draft', 'Landing portal persona description; applied bulk/single/immediate glossary + immutable->locked'),
  ('login.admin.point2', 'Form designer with maker-checker', 'مصمم النماذج بأسلوب فصل المُنشئ عن المعتمد', 'draft', 'Dropped ''Package'''),
  ('login.admin.why2', 'Every engine is a setting you control, not code.', 'كل أداة هي إعداد تتحكم به، لا كود برمجي.', 'draft', 'Simplified ''configuration under governance'''),
  ('login.footer', 'Access depends on your role. Every action is recorded.', 'الوصول يعتمد على دورك. يُسجَّل كل إجراء.', 'draft', 'Simplified role-scoped/audited, mirrors landing.footer.line'),
  ('login.inspector.why2', 'Check-in at the approved location proves you were there. The activity log proves the rest.', 'يثبت تسجيل الدخول في الموقع المعتمد أنك كنت هناك. ويثبت سجل النشاط الباقي.', 'draft', 'geofenced (inspector-facing) -> approved location; Audit Trail -> Activity Log'),
  ('login.portal.point1', 'Plan multiple visits, one visit, or an urgent visit', 'خطط زيارات متعددة، أو زيارة واحدة، أو زيارة عاجلة', 'draft', 'Bulk/single/immediate glossary applied to bullet'),
  ('login.portal.point2', 'Level 2 review with locked decisions', 'مراجعة المستوى الثاني بقرارات مقفلة', 'draft', 'immutable -> locked'),
