  ('mvp3.integrations.eventsError', 'API events could not be read. This is data that''s not available, not an empty event history.', 'تعذّرت قراءة أحداث واجهة البرمجة. هذه بيانات غير متاحة، وليست سجل أحداث فارغاً.', 'draft', 'API events error'),
  ('mvp3.integrations.exportsError', 'Export jobs could not be read. This is data that''s not available, not an empty export history.', 'تعذّرت قراءة مهام التصدير. هذه بيانات غير متاحة، وليست سجل تصدير فارغاً.', 'draft', 'Export jobs error'),
  ('mvp3.integrations.noEvents', 'No events visible to you. This is a checked, empty result.', 'لا توجد أحداث مرئية لك. هذه نتيجة فارغة تم التحقق منها.', 'draft', 'API events empty state'),
  ('mvp3.integrations.noExports', 'No export jobs visible to you. This is a checked, empty result.', 'لا توجد مهام تصدير مرئية لك. هذه نتيجة فارغة تم التحقق منها.', 'draft', 'Export jobs empty state'),
