  ('mvp3.operations.noErrors', 'No error records visible to you. This isn''t a claim about system health.', 'لا توجد سجلات أخطاء مرئية لك. هذا ليس ادعاءً بشأن صحة النظام.', 'draft', 'Error-queue table empty state'),
  ('mvp3.operations.policyHold', 'Retention, backup target, and restore goals are held by policy.', 'أهداف الاحتفاظ والنسخ الاحتياطي والاستعادة معلّقة بالسياسة.', 'draft', 'Retention/backup banner'),
  ('mvp3.operations.policyHoldBody', 'No purge or successful restore claim is turned on until approved values and evidence of the run exist.', 'لا يُفعَّل أي ادعاء بحذف أو استعادة ناجحة إلى أن توجد قيم معتمدة وأدلة على التنفيذ.', 'draft', 'Retention/backup banner body'),
  ('mvp3.operations.sourceUnavailable', 'This source is not available. We don''t claim it''s empty.', 'هذا المصدر غير متاح. لا نزعم أنه فارغ.', 'draft', 'Error-queue / feature-flags table error'),
  ('mvp3.operations.sourcesUnavailable', 'Some data sources aren''t available.', 'بعض مصادر البيانات غير متاحة.', 'draft', 'Sources-unavailable banner title'),
  ('mvp3.operations.sourcesUnavailableBody', 'Sources that aren''t available are listed below. They''re never shown as zero or empty.', 'مصادر البيانات غير المتاحة مدرجة أدناه. لا تُعرض أبداً كصفر أو فارغة.', 'draft', 'Sources-unavailable banner body'),
  ('mvp3.operations.title', 'System Operations and Resilience', 'عمليات النظام والمرونة', 'draft', 'Platform Operations -> System Operations glossary (Arabic-only fallback dict; no English literal in this file)'),
  ('mvp3.security.noGrants', 'No evidence grants visible to you.', 'لا توجد منح أدلة مرئية لك.', 'draft', 'Evidence grants empty state'),
