  ('ops.actions.dueDate (inline, no key)', 'No due date set', 'لا يوجد تاريخ استحقاق محدد', 'draft', 'Corrective action card fallback when no due date exists. Was ''No governed due date'' — dropped ''governed''.'),
  ('ops.alerts.body', 'Action forms and notification status you can see here. The database still protects any changes.', 'نماذج الإجراءات وحالة الإشعارات التي يمكنك رؤيتها هنا. لا تزال قاعدة البيانات تحمي أي تغييرات.', 'draft', 'Body under ''Operational alerts and corrective actions''. Was ''Current RLS-scoped action forms and notification delivery states. Changes remain guarded by database policy.'''),
  ('ops.cancellations.body', 'Recent cancellation requests, reasons and final decisions you can see. These decisions can''t change.', 'طلبات الإلغاء الأخيرة وأسبابها والقرارات النهائية التي يمكنك رؤيتها. لا يمكن تغيير هذه القرارات.', 'draft', 'Body under ''Cancellation monitoring''. Was ''Recent RLS-scoped cancellation requests, reasons and immutable decision outcomes.'''),
  ('ops.decisions.readOnly', 'These decisions are read-only for your role', 'هذه القرارات للقراءة فقط بالنسبة لدورك', 'draft', 'Empty-state title shown to roles without decision rights. Was ''Operational decisions are read-only for your role'' — dropped the ''Operational'' jargon adjective.'),
  ('ops.export.auditRequired', 'Every file needs a matching database receipt for your role and region, plus a recorded audit event, before you can download it.', 'يحتاج كل ملف إلى إيصال مطابق من قاعدة البيانات لدورك ومنطقتك، بالإضافة إلى حدث تدقيق مسجّل، قبل أن تتمكن من تنزيله.', 'draft', 'Export requirement note. Was ''Every file requires a matching role- and region-scoped database receipt plus an atomic audit event before download.'''),
  ('ops.export.heading', 'Export data', 'تصدير البيانات', 'draft', 'Export section heading. Was ''Export operational data'' — dropped jargon adjective.'),
  ('ops.highlights.override', 'Location exception decision required', 'يلزم قرار بشأن استثناء الموقع', 'draft', 'Highlights feed label for a pending geo-override. Was ''Override decision required''.'),
  ('ops.history.body', 'The last 100 events from the location history log you can see. These records are never changed here.', 'آخر 100 حدث من سجل تاريخ الموقع الذي يمكنك رؤيته. لا يتم تغيير هذه السجلات هنا أبدًا.', 'draft', 'Body under the history section. Was ''Latest 100 events from the append-only, RLS-scoped geo-event ledger. The source rows are never edited here.'''),
  ('ops.history.heading', 'Location and visit status history', 'سجل الموقع وحالة الزيارة', 'draft', 'Section heading. Was ''Immutable location and operational history'' — dropped ''Immutable'' (the body already plainly says records are never edited) and applied ''operational -> visit status''.'),
  ('ops.kpi.contractHeading', 'Operations KPI contract', 'عقد مؤشرات أداء العمليات', 'draft', 'Section heading. Was ''Governed Operations KPI contract'' — dropped ''Governed''; kept ''contract'' as it''s an established domain term used consistently across this feature (operations_kpi_contract RPC, other nearby strings).'),
  ('ops.kpi.metric.sla_breach_rate (inline, no key)', 'Deadline breach rate', 'معدل تجاوز الموعد النهائي', 'draft', 'KPI contract metric label. Was ''SLA breach rate'' — Operations Center is an ordinary supervisor surface, not admin/config, so SLA maps to Deadline.'),
  ('ops.kpi.notConfigured', 'Policy or published metric definitions are not set up. Undefined formulas stay unavailable.', 'لم يتم إعداد السياسة أو تعريفات المؤشرات المنشورة. تبقى الصيغ غير المحددة غير متاحة.', 'draft', 'KPI contract not-configured body. Was a lowercase-leading semicolon fragment: ''policy or published metric definitions are not configured; undefined formulas remain unavailable.'' Split into two proper sentences.'),
  ('ops.live.factorySourceUnavailable', 'Factory marker data is unavailable. Inspector positions still show on their own.', 'مصدر مؤشرات المصانع غير متاح. تبقى مشاهدات المفتشين مستقلة ومحدودة.', 'draft', 'Was ''Factory marker source is unavailable. Inspector observations remain independently bounded.'' — dropped ''independently bounded'' jargon.'),
  ('ops.live.freshnessPolicy', 'We don''t track data freshness yet — showing the last recorded time only.', 'لم يُضبط معيار حداثة البيانات بعد — يُعرض وقت آخر رصد فقط.', 'draft', 'Was ''Staleness cadence not yet configured — showing last-observed time only.'' — dropped dev-jargon ''staleness cadence''.'),
  ('ops.live.operationalState', 'Visit status', 'حالة الزيارة', 'draft', 'Inspector-detail panel field label on the live map. Was ''Operational state'' regression.'),
  ('ops.live.partialSource', 'Position data is unavailable. Active visits still appear, without a location.', 'مصدر المواقع غير متاح. تبقى الزيارات النشطة مدرجة دون ادعاءات عن الموقع.', 'draft', 'Was ''Position source is unavailable. Active visits remain listed without location claims.'''),
  ('ops.live.scopeNote', 'Records limited to your access', 'سجلات محدودة بصلاحية الوصول لديك', 'draft', 'Caption under the live monitoring table. Was ''RLS-scoped monitoring records'' — raw dev jargon leaking into UI.'),
  ('ops.loading.desc', 'Loading visits, location events, corrective actions and notifications.', 'جارٍ تحميل الزيارات وأحداث الموقع والإجراءات التصحيحية والإشعارات.', 'draft', 'Route-loading skeleton status text. Was ''Fetching visits, geo events, corrective actions and notifications through RLS.'' — raw ''RLS'' was directly user-visible in aria-live status text.'),
  ('ops.map.factoryLabel (inline, no key)', 'Factory list location', 'موقع من قائمة المصانع', 'draft', 'Map pin label fallback when a factory has no active visit pin — shows the factory''s on-record coordinate. Was ''Factory registry coordinate'' — regression of registry -> Factory list.'),
  ('ops.map.list.description', 'The list and map show the same records you can see.', 'تعرض القائمة والخريطة نفس السجلات التي يمكنك الاطلاع عليها.', 'draft', 'Map workspace list/map parity note. Was ''The list and map use the same RLS-scoped records.'''),
  ('ops.monitoring.body', 'Visit status, assignments and the latest recorded geofence results you can see.', 'حالة الزيارة والتكليفات وأحدث نتائج نطاق الموقع المسجّلة التي يمكنك رؤيتها.', 'draft', 'Body under ''Visit and inspector monitoring'' heading. Was ''Current RLS-scoped operational states, assignments and latest recorded geofence results.'''),
  ('ops.override.approve', 'Approve exception', 'الموافقة على الاستثناء', 'draft', 'Decision button in the geo-override queue. Was ''Approve override''.'),
  ('ops.override.empty.desc', 'Location exception requests with their evidence appear here for Operations review.', 'تظهر طلبات استثناء الموقع مع أدلتها هنا لمراجعة العمليات.', 'draft', 'Was ''Outside-fence requests with their evidence appear here for Operations review.'''),
  ('ops.override.empty.title', 'No location exceptions pending', 'لا توجد استثناءات موقع معلّقة', 'draft', 'Empty state for the geo-override queue. Was ''No override approvals pending'' — realigned wording with the queue''s already-correct ''Location exception requests'' heading.'),
  ('ops.preview.operationalState', 'Visit status', 'حالة الزيارة', 'draft', 'Inspector/factory preview drawer field label. Was ''Operational state'' — direct regression of the ''operational (column) -> Visit status'' glossary rule.'),
  ('ops.preview.riskRank', 'Visible rank', 'الترتيب المرئي', 'draft', 'Preview drawer risk-rank field label. Was ''RLS-visible rank'' — raw dev jargon.'),
  ('ops.sla.body', 'Deadlines use server timestamps and deadline rules that are set up. If those rules are missing, this stays unavailable.', 'تعتمد المواعيد النهائية على توقيتات الخادم وقواعد المواعيد المُعدّة. إذا كانت هذه القواعد مفقودة، تبقى الحالة غير متاحة.', 'draft', 'Body under the deadline/resubmission section. Was ''Deadlines use server timestamps and governed SLA configuration. Missing configuration remains unavailable.'' — dropped ''governed'', kept ''unavailable'' as the app''s accepted absent-data state word.'),
  ('ops.sla.empty', 'No deadline alerts in this scope', 'لا توجد تنبيهات مواعيد نهائية ضمن هذا النطاق', 'draft', 'Empty state title. Was ''No governed deadline alerts in this scope'' — dropped ''governed''.'),
  ('ops.sla.heading', 'Deadline and resubmission alerts', 'تنبيهات المواعيد النهائية وإعادة التقديم', 'draft', 'Section heading. Was EN ''SLA and resubmission monitoring'' while the existing Arabic already said ''Deadline alerts'' — EN/AR were out of sync; realigned both to match the SLA->Deadline glossary rule.'),
  ('ops.timeline.body', 'The full order of events, from planning through inspection, review and handoff to Compliance.', 'التسلسل الكامل للأحداث، من التخطيط مرورًا بالتفتيش والمراجعة والتسليم إلى الامتثال.', 'draft', 'Body under Visit timeline. Was ''Canonical chronology from planning through lifecycle, inspection, review and Compliance handoff.'' — dropped Latinate ''Canonical chronology''/''lifecycle''; kept ''Compliance'' as a precise legal noun per instructions.'),
  ('ops.timeline.heading', 'Visit timeline', 'الجدول الزمني للزيارة', 'draft', 'Section heading. Was ''Operational timeline''; renamed to match the plain ''Choose a visit timeline'' wording already used in the same section.'),
  ('ops.timeline.select', 'Select a visit to load its timeline', 'اختر زيارة لتحميل جدولها الزمني', 'draft', 'Empty-state prompt. Was ''Select a visit to load its governed timeline'' — dropped ''governed''.'),
  ('ops.timeline.unavailable', 'Visit timeline unavailable', 'الجدول الزمني للزيارة غير متاح', 'draft', 'Error empty-state title, matched to the renamed ''Visit timeline'' heading. Was ''Operational timeline unavailable''.'),
  ('ops.unauthorized.body', 'This page is not turned on for your account, so no data has loaded.', 'هذه الصفحة غير مفعّلة لحسابك، لذلك لم يتم تحميل أي بيانات.', 'draft', 'Empty-state body when the /operations or /operations/live destination is not in the caller''s navigation. Was: ''No operational data has been loaded because this destination is not enabled in your assigned navigation.'' No inline Arabic source existed for this key; Arabic authored fresh, natural MSA.'),
  ('plan.bulk.ai.unavailable', 'AI is not available right now — nothing was generated or changed.', 'الذكاء الاصطناعي غير متاح حاليًا — لم يتم إنشاء أو تغيير أي شيء.', 'draft', 'Was ''AI provider unavailable...''. No inline AR existed; AR authored fresh.'),
  ('plan.bulk.criteria.nsEmployeeCount', 'Employee count is recorded for only 4 of 1,339 factories — far too few to target by.', 'عدد الموظفين مسجَّل لأربعة مصانع فقط من أصل 1,339 — عدد ضئيل جدًا للاستهداف به.', 'draft', 'Minor rewording for consistency with the other ns* strings (no banned term present, simplified phrasing only).'),
  ('plan.bulk.criteria.nsIssuingAuthority', 'Issuing authority is not filled in yet, so it can''t be used to target by.', 'جهة الإصدار غير مُدخلة بعد، لذا لا يمكن استخدامها للاستهداف.', 'draft', '''not a governed, populated attribute'' -> plain wording.'),
  ('plan.bulk.criteria.nsLandProvider', 'There is no land-provider field in the factory data.', 'لا يوجد حقل لمزوّد الأرض في بيانات المصنع.', 'draft', '''governed factory model'' -> plain ''factory data''.'),
  ('plan.bulk.criteria.nsLicenseStage', 'Licence stage is filled in for only about 1% of the licence list — too little to target by.', 'مرحلة الترخيص مُدخلة لنحو 1٪ فقط من قائمة التراخيص — نسبة قليلة جدًا للاستهداف بها.', 'draft', 'Was ''...too sparse to target against honestly.'' — simplified; ''licence register'' left as-is (different domain object, not the app''s own Factory list).'),
  ('plan.bulk.criteria.nsLicenseStatus', 'Licence status is filled in for only about 1% of the licence list — too little to target by.', 'حالة الترخيص مُدخلة لنحو 1٪ فقط من قائمة التراخيص — نسبة قليلة جدًا للاستهداف بها.', 'draft', 'Same pattern as nsLicenseStage.'),
  ('plan.bulk.criteria.nsProductHs', 'Product / HS codes exist for only 4 factories — not enough to target by yet.', 'توجد رموز المنتج / التصنيف الجمركي لأربعة مصانع فقط — عدد غير كافٍ للاستهداف بها حاليًا.', 'draft', '''not a governed targeting source yet'' -> plain wording.'),
  ('plan.bulk.criteria.nsSector', 'There is no sector data set up yet — this can''t be checked, and is never treated as blank.', 'لا توجد بيانات قطاع معدّة بعد — لا يمكن فحص هذا البعد، ولا يُعامل أبدًا كقيمة فارغة.', 'draft', 'Criteria-builder ''not-supplied'' explainer; ''governed sector source'' -> plain wording. No inline AR existed; AR authored fresh.'),
  ('plan.bulk.noCriteria.body', 'Bulk targeting never matches the whole Factory list by default. Add at least one criterion below to see matching factories. Nothing is selected or sent without a clear scope.', 'لا يطابق الاستهداف الجماعي كل قائمة المصانع تلقائيًا. أضف معيارًا واحدًا على الأقل أدناه لعرض المصانع المطابقة. لا يتم اختيار أو إرسال أي شيء دون نطاق واضح.', 'draft', 'Regression fix: ''the whole registry'' -> ''the whole Factory list'' (this refers to the app''s own factory list). Also simplified ''explicit scope'' -> ''clear scope'' and ''published'' -> ''sent''.'),
  ('plan.bulk.serviceUnavailable.body', 'We couldn''t load the Factory list. Nothing was filtered or published. Try again once access is fixed.', 'تعذّر تحميل قائمة المصانع. لم يتم تصفية أو نشر أي شيء. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Was ''The Factory list could not be read through the authorized Planning path...''. No inline AR existed; AR authored fresh.'),
  ('plan.bulk.serviceUnavailable.title', 'Factory list not available', 'قائمة المصانع غير متاحة', 'draft', 'Was ''Factory list unavailable''. No inline AR existed; AR authored fresh.'),
  ('plan.bulk.unauthorized.body', 'Plan multiple visits needs Planner or Supervisor access.', 'يتطلب تخطيط زيارات متعددة صلاحية المخطط أو المشرف.', 'draft', 'Was ''Plan multiple visits requires the bulk-planning capability (Planner or Supervisor).'''),
  ('plan.bulk.unauthorized.title', 'You don''t have permission', 'ليست لديك الصلاحية اللازمة', 'draft', 'Was ''Authorized role required''.'),
  ('plan.bulk.unavailable', 'Planning data is not available right now. Nothing was changed. Try again once access is fixed.', 'بيانات التخطيط غير متاحة حاليًا. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Was ''The authorized Planning read path is unavailable...''. No inline AR existed; AR authored fresh.'),
  ('plan.drill.invalidId', 'The plan reference is not valid. Go back to Visit plans and choose one that exists.', 'مرجع الخطة غير صالح. ارجع إلى خطط الزيارات واختر خطة متاحة.', 'draft', 'Was ''The plan reference is invalid. Return to the plan register and choose an available plan.'' — fixes the ''plan register'' regression to glossary term ''Visit plans'' and simplifies wording.'),
  ('plan.drill.loadErrorSafe', 'We couldn''t load the plan. Nothing was changed. Try again once access is fixed.', 'تعذّر تحميل الخطة. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Was ''Could not load the plan through the authorized read path...''. No inline AR existed; AR authored fresh.'),
  ('plan.drill.unauthorized.body', 'You need planning access to view plan details.', 'يلزم صلاحية تخطيط لعرض تفاصيل الخطة.', 'draft', 'Was ''Viewing plan details requires an authorized planning capability.'''),
  ('plan.drill.unavailable.body', 'We couldn''t check your access to this plan. Nothing was changed. Try again once access is fixed.', 'تعذّر التحقق من صلاحية الوصول إلى هذه الخطة. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Dropped ''Planning read contract'' jargon.'),
  ('plan.drill.unavailable.title', 'Plan not available', 'الخطة غير متاحة', 'draft', 'Was ''Plan unavailable''.'),
  ('plan.home.unauthorized.body', 'Only planning staff can use Visit Planning.', 'تخطيط الزيارات متاح لموظفي التخطيط فقط.', 'draft', 'Was ''Visit Planning is available to authorized planning staff.'''),
  ('plan.home.unauthorized.title', 'You don''t have permission', 'ليست لديك الصلاحية اللازمة', 'draft', 'Shared key used as the title on every role-gated empty state across Planning (was ''Authorized role required''); simpler, plain-language access-denied heading.'),
  ('plan.home.unavailable.body', 'We couldn''t check your access to Planning. Nothing was created or changed. Try again once access is fixed.', 'تعذّر التحقق من صلاحية الوصول إلى التخطيط. لم يتم إنشاء أو تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Dropped ''planning workspace read contract'' jargon; used twice on this page.'),
  ('plan.home.unavailable.title', 'Planning data not available', 'بيانات التخطيط غير متاحة', 'draft', 'Was ''Planning data unavailable'' — simple word-order fix, used twice on this page.'),
  ('plan.imm.manualLockedLookups', 'Manual entry is not available — we couldn''t load reference data.', 'الإدخال اليدوي غير متاح — تعذر تحميل البيانات المرجعية.', 'draft', '''is unavailable'' -> ''is not available''; body clause made active voice.'),
  ('plan.imm.priority', 'Priority (no approved list yet)', 'الأولوية (لا توجد قائمة معتمدة بعد)', 'draft', '''(ungoverned — no approved value list)'' -> plain ''(no approved list yet)''. No inline AR existed; AR authored fresh.'),
  ('plan.imm.r05BlockedBody', 'Urgency only changes the response time — not who is checked or who supervises. Choose a registered factory; you can''t enter one that isn''t registered.', 'لا تغيّر العجلة سوى وقت الاستجابة — لا هوية الهدف ولا الإشراف. اختر مصنعاً مسجلاً؛ لا يمكن إدخال مصنع غير مسجل.', 'draft', '''target identity or supervision'' and ''unregistered entry is unavailable'' -> plain, active-voice wording.'),
  ('plan.imm.unauthorized.body', 'Only Planner and Supervisor roles can use Create an urgent visit. Inspectors raise urgent issues from their own assigned work.', 'إنشاء زيارة عاجلة متاح للمخطط والمشرف فقط. يرفع المفتشون البلاغات العاجلة من عملهم المكلّفين به.', 'draft', '''available to Planner and Supervisor roles'' -> ''Only Planner and Supervisor roles can use''; ''raise urgent escalations'' -> ''raise urgent issues''.'),
  ('plan.imm.unauthorized.title', 'You don''t have permission', 'ليست لديك الصلاحية اللازمة', 'draft', 'Was ''Authorized role required''.'),
  ('plan.list.exportUnauthorized', 'Your account can''t export this.', 'لا يمكن لحسابك تصدير هذا.', 'draft', 'ExportButton failure message; ''authorized'' -> plain ''can''t''.'),
  ('plan.method.immediate.desc', 'Submit an urgent request for one registered factory. A Supervisor assigns and releases it within the set response time.', 'أرسل طلبًا عاجلاً لمصنع واحد مسجل. يقوم المشرف بالإسناد والإصدار خلال مدة الاستجابة المحددة.', 'draft', 'Method-tile description on Planning home; ''governed response window'' -> plain ''set response time''. No inline AR existed; AR authored fresh.'),
  ('plan.read.failure.body', 'Planning data is not available right now. Nothing was changed. Try again once access is fixed.', 'بيانات التخطيط غير متاحة حاليًا. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Shared key; was ''The required planning read contract is unavailable...''. No inline AR existed; AR authored fresh.'),
  ('plan.referenceUnavailable', 'Reference not available', 'المرجع غير متاح', 'draft', 'Fallback shown when a plan/visit reference number is null; simpler adjective order (''unavailable'' -> ''not available'').'),
  ('plan.register.loadErrorSafe', 'We couldn''t load the plans. Nothing was changed. Try again once access is fixed.', 'تعذّر تحميل الخطط. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Load-error banner on Visit plans list; removed ''authorized read path'' jargon. No inline AR existed (2-arg t()); AR authored fresh.'),
  ('plan.register.unauthorized.body', 'You need planning access to view visit plans.', 'يلزم صلاحية تخطيط لعرض خطط الزيارات.', 'draft', 'Was ''Viewing visit plans requires an authorized planning capability.'''),
  ('plan.register.unavailable.body', 'We couldn''t check your access to visit plans. Nothing was changed. Try again once access is fixed.', 'تعذّر التحقق من صلاحية الوصول إلى خطط الزيارات. لم يتم تغيير أي بيانات. حاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Body for the same empty state; dropped ''read contract'' dev jargon and ''access configuration is restored'' formality.'),
  ('plan.register.unavailable.title', 'Visit plans not available', 'خطط الزيارات غير متاحة', 'draft', 'Empty-state title when access check fails on the Visit plans list (was ''Plan register unavailable'' — regression fix to glossary term + simpler English).'),
  ('plan.review.bl.srci.t', 'Inspector data is not available', 'بيانات المفتش غير متاحة', 'draft', 'Was ''Inspector source is unavailable''. No inline AR existed; AR authored fresh.'),
  ('plan.review.bl.srcp.t', 'Inspection checklist data is not available', 'بيانات قائمة التفتيش غير متاحة', 'draft', 'Was ''Inspection checklist source is unavailable''. No inline AR existed; AR authored fresh.'),
  ('plan.review.draftUnavailable', 'We couldn''t load this draft. It may have been published, archived, or created by someone else. Using your last selection instead.', 'تعذّر تحميل هذه المسودة. ربما تم نشرها أو أرشفتها أو أنشأها شخص آخر. سيتم استخدام اختيارك الأخير بدلاً منها.', 'draft', '''Falling back to the browser-held selection'' -> plain wording. No inline AR existed; AR authored fresh.'),
  ('plan.review.unavailable', 'Planning data is not available right now. Go back to targeting and try again once access is fixed.', 'بيانات التخطيط غير متاحة حاليًا. ارجع إلى صفحة الاستهداف وحاول مرة أخرى بعد إصلاح الوصول.', 'draft', 'Was ''The authorized Planning read path is unavailable...''. No inline AR existed; AR authored fresh.'),
  ('plan.single.exactRule', 'Matches an exact identifier (CR, factory code or Industrial License)', 'يطابق مُعرّفًا بدقة (رقم السجل التجاري أو رمز المصنع أو الترخيص الصناعي)', 'draft', '''governed identifier'' -> plain ''exact identifier''. No inline AR existed; AR authored fresh.'),
  ('plan.single.licenceRequired', 'Select one license / plant to continue — a single visit targets one plant, never the whole CR (CR-level planning is not allowed here).', 'اختر ترخيصًا / منشأة واحدة للمتابعة — تستهدف الزيارة الفردية منشأة واحدة، وليس السجل التجاري كاملاً (التخطيط على مستوى السجل التجاري غير مسموح هنا).', 'draft', '''not eligible here'' -> ''not allowed here'' (simpler word).'),
  ('plan.single.registryUnavailable', 'The Factory list is not available right now — try your search again.', 'قائمة المصانع غير متاحة حاليًا — أعد المحاولة.', 'draft', '''temporarily unavailable'' -> ''not available right now''. No inline AR existed; AR authored fresh.'),
  ('plan.single.unauthorized.body', 'Only planning staff can use Plan one visit.', 'تخطيط زيارة واحدة متاح لموظفي التخطيط فقط.', 'draft', 'Was ''Plan one visit is available to authorized planning staff.'''),
  ('plan.single.unauthorized.title', 'You don''t have permission', 'ليست لديك الصلاحية اللازمة', 'draft', 'Was ''Authorized role required''.'),
