  ('report.hist.immutable', 'final', 'نهائي', 'draft', 'Badge word next to submission version number.'),
  ('report.integrityBlocked.body', 'This inspection is marked as approved, but it has no final submitted version on file. The approval is not valid. Don’t treat it as an official decision until a final submission exists (DEF-WF-006).', 'هذا التفتيش مُسجَّل كمعتمد، لكن لا يوجد له إصدار مُقدَّم نهائي في السجل. الاعتماد غير صالح. لا تتعامل معه كقرار رسمي إلى أن يتوفر تقديم نهائي (DEF-WF-006).', 'draft', 'Split long sentence, replaced ''immutable submitted version''/''immutable submission'' with ''final submitted version''/''final submission''; kept DEF-WF-006 traceability code.'),
  ('report.integrityBlocked.status', 'approval invalid — no final submitted version', 'الاعتماد غير صالح — لا يوجد إصدار مُقدَّم نهائي', 'draft', 'Applied glossary: immutable submitted version (ordinary user) -> Final submitted version.'),
  ('report.integrityBlocked.title', 'Data problem — invalid approval', 'مشكلة في البيانات — اعتماد غير صالح', 'draft', 'Simplified ''Data-integrity defect'' to plainer wording.'),
  ('report.items.heading', 'Checklist responses — final version v{n}', 'إجابات قائمة التحقق — الإصدار النهائي v{n}', 'draft', 'immutable v{n} -> final version v{n}; {n} placeholder preserved.'),
  ('report.loadError', 'The inspection report isn’t available right now. Nothing changed. Try again.', 'تقرير التفتيش غير متاح حالياً. لم يتغيّر أي شيء. حاول مرة أخرى.', 'draft', 'Report load-failure message; removed ''temporarily unavailable'' Latinate phrasing.'),
  ('report.notFound', 'Report not available — this inspection isn’t in your scope, or it doesn’t exist.', 'التقرير غير متاح — هذا التفتيش خارج نطاقك، أو غير موجود.', 'draft', 'Stripped the ''(RLS)'' dev-jargon acronym from a user-visible banner.'),
  ('report.notSubmitted.body', 'The official report comes from the submitted version snapshot. The identity and visit details below are live records.', 'يُبنى التقرير الرسمي من لقطة الإصدار المُقدَّم. بيانات الهوية وتفاصيل الزيارة أدناه سجلات حية.', 'draft', 'Split sentence, ''configuration'' -> ''details'' for consistency with report.visit.heading.'),
  ('report.notSubmitted.title', 'No final submission yet.', 'لا يوجد تقديم نهائي بعد.', 'draft', 'immutable -> final.'),
  ('report.visit.heading', 'Visit details', 'تفاصيل الزيارة', 'draft', 'Simplified ''Visit configuration'' -> plain-English ''Visit details''.'),
  ('report.visit.package', 'Checklist version used for the inspection', 'إصدار قائمة التحقق المستخدم في التفتيش', 'draft', 'Glossary: frozen package definition -> Checklist version used for the inspection (was ''Checklist package (locked)'').'),
  ('review.cmp.catUnavailable', 'Not available', 'غير متاح', 'draft', 'scope-rail category label'),
  ('review.cmp.collectionHeading', 'Fixed collection comparison', 'مقارنة المجموعات الثابتة', 'draft', 'glossary/simple-English fix: ''Immutable collection comparison'' -> ''Fixed collection comparison'''),
  ('review.cmp.collectionUnavailable', 'Not available in one or both fixed snapshots — not treated as unchanged.', 'غير متاح في إحدى اللقطتين الثابتتين أو كلتيهما — ولا يُعامل كأنه لم يتغير.', 'draft', 'collection diff empty/unavailable note'),
  ('review.cmp.sourceUnavailable', 'Comparison source not available.', 'مصدر المقارنة غير متاح.', 'draft', 'compare tab fallback when submission-version data failed to load'),
  ('review.cmp.sourceUnavailableBody', 'We could not load submitted-version data for this record, so we cannot show a comparison. This is not available, not an empty result.', 'تعذّر تحميل بيانات الإصدار المُقدَّم لهذا السجل، لذا لا يمكننا عرض المقارنة. هذا غير متاح، وليس نتيجة فارغة.', 'draft', 'same fallback, body text'),
  ('review.cmp.unavailEvidence', 'Evidence / media comparison — not shown; marked not available, never ''unchanged''.', 'مقارنة الأدلة/الوسائط — غير معروضة؛ توسم كغير متاحة، ولا تُعامل أبداً كأنها لم تتغير.', 'draft', 'compare tab, not-derived comparisons panel'),
  ('review.cmp.unavailMetadata', 'Metadata / section-order comparison — not compared.', 'مقارنة البيانات الوصفية/ترتيب الأقسام — غير مقارنة.', 'draft', 'compare tab, not-derived comparisons panel'),
  ('review.cmp.unavailNote', 'These are honestly not available, not equal.', 'هذه العناصر غير متاحة فعليًا، وليست متطابقة.', 'draft', 'footer note; dropped HANDOFF_BLOCKED_* internal codes from visible text'),
  ('review.cmp.unavailPackage', 'Checklist-meaning comparison — we do not check whether an answer means the same thing across checklist versions.', 'مقارنة معنى قائمة الفحص — لا نتحقق مما إذا كانت الإجابة تحمل المعنى نفسه عبر إصدارات قائمة الفحص.', 'draft', 'glossary fix: ''Package-semantic comparison'' -> ''Checklist-meaning comparison'' (inspection package -> checklist)'),
  ('review.list.degradedBody', 'The queue loaded, but we could not read one or more linked sources. Those facts stay not available.', 'تم تحميل القائمة، لكن تعذّرت قراءة مصدر واحد أو أكثر من المصادر المرتبطة. تبقى تلك الحقائق غير متاحة.', 'draft', 'degraded-data banner body (dropped RLS-scoped)'),
  ('review.list.degradedTitle', 'Some linked information is not available', 'بعض المعلومات المرتبطة غير متاحة', 'draft', 'degraded-data banner title'),
  ('review.list.empty', 'No inspections waiting for review', 'لا توجد تفتيشات بانتظار المراجعة', 'draft', 'empty-state title on /reviews (glossary: Queue clear -> No inspections waiting for review)'),
  ('review.list.emptyBody', 'No reviews in your scope are waiting for a decision.', 'لا توجد مراجعات ضمن نطاقك بانتظار قرار.', 'draft', 'empty-state body, dropped ''Level 2 decision'''),
  ('review.list.fp.slaUnavailable', 'Deadline not available — a needed setting or timestamp is missing', 'الموعد النهائي غير متاح — يوجد إعداد أو طابع زمني مفقود', 'draft', 'deadline chip tooltip when no deadline can be computed'),
  ('review.list.fp.unassignedBlocked', 'claim/reassign not available', 'المطالبة/إعادة التعيين غير متاحة', 'draft', 'tag next to unassigned reviewer row'),
  ('review.list.fp.unavailable', 'not available', 'غير متاح', 'draft', 'generic ''unavailable'' fact value in readiness chips'),
  ('review.list.fpHint', 'Facts come from records you are allowed to see. Facts we cannot read stay marked as not available.', 'تأتي الحقائق من السجلات المسموح لك بالاطلاع عليها. الحقائق التي لا يمكننا قراءتها تبقى موسومة كغير متاحة.', 'draft', 'readiness fingerprint hint text (dropped RLS-scoped)'),
  ('review.list.immutableBody', '— decided reviews cannot be edited. Each resubmission creates a new, saved version.', '— لا يمكن تعديل المراجعات المقررة. تُنشئ كل عملية إعادة تقديم إصدارًا جديدًا محفوظًا.', 'draft', 'immutability banner body'),
  ('review.list.immutableTitle', 'Decisions cannot be changed', 'لا يمكن تغيير القرارات', 'draft', 'immutability banner title'),
  ('review.list.missingSlaBody', 'We cannot work out a review deadline. Rows show as not available instead of on time.', 'لا يمكننا احتساب موعد نهائي للمراجعة. تظهر الصفوف كغير متاحة بدلاً من في الوقت المحدد.', 'draft', 'same banner, body text'),
  ('review.list.missingSlaTitle', 'Deadline settings missing', 'إعدادات الموعد النهائي مفقودة', 'draft', 'banner shown when review_business_days config is absent (SLA -> Deadline, ordinary-user surface)'),
  ('review.list.openHint', 'Opens the review as read-only. Starting and deciding happen there, and we record both.', 'يفتح المراجعة للقراءة فقط. يتم بدء المراجعة واتخاذ القرار هناك، ونسجّل كلا الإجراءين.', 'draft', 'tooltip on the Open review row action'),
  ('review.list.scanBody', 'Opening only lets you look. Starting and deciding are separate actions, and we record both.', 'الفتح يتيح لك الاطلاع فقط. بدء المراجعة واتخاذ القرار إجراءان منفصلان، ونسجّل كليهما.', 'draft', 'Review overview banner (dropped ''workspace'')'),
  ('review.list.submissionBlockBody', 'We cannot yet confirm that a brand-new inspection submission works end to end. Existing review records you have access to are still readable; this queue does not get around that limit.', 'لا يمكننا حتى الآن تأكيد أن تقديم تفتيش جديد تمامًا يعمل من البداية إلى النهاية. سجلات المراجعة الحالية التي يمكنك الوصول إليها تبقى قابلة للقراءة؛ لا تتجاوز هذه القائمة هذا القيد.', 'draft', 'submission-integrity banner body (dropped ''RLS-visible'', ''platform blocker'')'),
  ('review.list.submissionBlockTitle', 'New submissions are not confirmed working', 'التقديمات الجديدة غير مؤكدة العمل بعد', 'draft', 'submission-integrity banner title'),
  ('review.list.unauthBody', 'This queue needs an allowed role — review, planning, operations, or assigned inspector — with matching scope. Being visible in navigation does not mean you have access.', 'تتطلب هذه القائمة دورًا مسموحًا به — مراجعة أو تخطيط أو عمليات أو مفتشًا معيّنًا — بنطاق مطابق. ظهورها في التنقل لا يعني أن لديك صلاحية الوصول.', 'draft', 'unauthorized banner on /reviews list'),
  ('review.ws.comment', 'Reviewer comment (cannot be changed once saved)', 'تعليق المراجع (لا يمكن تعديله بعد حفظه)', 'draft', 'decision panel comment field label'),
  ('review.ws.commentPlaceholder', 'Optional comment, saved on its own and cannot be changed', 'تعليق اختياري يُحفظ بشكل مستقل ولا يمكن تعديله', 'draft', 'decision panel comment field placeholder'),
  ('review.ws.dec032.body', 'DEC-032 is unresolved. Review evidence and the returned scope stay visible, but Approve, Return and Reject stay disabled, so this screen cannot show a false successful step.', 'القرار DEC-032 غير محسوم. تبقى الأدلة ونطاق الإرجاع ظاهرين، لكن تظل إجراءات الاعتماد والإرجاع والرفض معطلة حتى لا تعرض هذه الشاشة خطوة ناجحة غير صحيحة.', 'draft', 'DEC-032 blocked-decision gate body'),
  ('review.ws.dec032.title', 'Decision controls are not available right now', 'أدوات القرار غير متاحة حالياً', 'draft', 'DEC-032 blocked-decision gate title'),
  ('review.ws.evidenceReference', 'Fixed reference', 'مرجع ثابت', 'draft', 'evidence table column header, was ''Immutable reference'''),
  ('review.ws.fvError', 'Verification data is not available right now. We cannot show the source-versus-observed comparison yet.', 'بيانات التحقق غير متاحة حالياً. لا يمكننا عرض مقارنة المصدر مقابل الملاحظ بعد.', 'draft', 'factory verification tab error text'),
  ('review.ws.hashUnavailable', 'not available', 'غير متاحة', 'draft', 'sha256 fallback text in evidence table'),
  ('review.ws.immutable', 'final', 'نهائي', 'draft', 'parenthetical tag on prior-decision banner, was ''immutable'''),
  ('review.ws.loadErrorDesc', 'We could not load the record. Something may be wrong with the data source. Try again.', 'تعذّر تحميل السجل. قد تكون هناك مشكلة في مصدر البيانات. حاول مرة أخرى.', 'draft', 'load-error state, used in 3 places (auth error, role error, not-found)'),
  ('review.ws.mediaPreviewUnavailable', 'We cannot show media files here because there is no allowed, safe link for them on this page. The details stay read-only, and the app does not show or guess a public link.', 'لا يمكن معاينة محتوى الوسائط لعدم توفر رابط آمن ومعتمد له في هذه الصفحة. تبقى البيانات للقراءة فقط، ولا تعرض الواجهة رابطاً عاماً أو تفترضه.', 'draft', 'evidence tab caption, dropped ''authorized signed-URL contract'' jargon'),
  ('review.ws.readOnlyBody', 'You cannot edit this content — the database blocks it (proven B3). To fix something, use Return with the exact scope.', 'لا يمكنك تعديل هذا المحتوى — تمنعه قاعدة البيانات (مُثبت B3). لإجراء تصحيح، استخدم الإرجاع بالنطاق الدقيق.', 'draft', 'same banner, body'),
  ('review.ws.readOnlyNote', 'Read-only for this role — only Level 2 Reviewer / Operations can use the decision controls.', 'للقراءة فقط لهذا الدور — يمكن فقط لمراجع المستوى الثاني/العمليات استخدام أدوات القرار.', 'draft', 'read-only-role note next to decision panel, kept role name ''Level 2 Reviewer'' (canonical role title per lib/persona.ts)'),
  ('review.ws.readOnlyTitle', 'Final submitted version.', 'الإصدار النهائي المُقدَّم.', 'draft', 'glossary fix: immutable submitted version -> Final submitted version'),
  ('review.ws.startBody', 'Opening this record does not change anything (CD-028). Starting the review claims it for you and moves the inspection to under review — an action we record.', 'فتح هذا السجل لا يغيّر أي شيء (CD-028). بدء المراجعة يخصصها لك وينقل التفتيش إلى قيد المراجعة — وهو إجراء نسجّله.', 'draft', 'Start review panel body'),
  ('review.ws.startTitle', 'Start review', 'بدء المراجعة', 'draft', 'glossary fix: dropped ''Level 2'' qualifier, keeps role name ''Level 2 Reviewer'' elsewhere untouched'),
  ('review.ws.timelineHeading', 'Official review timeline', 'الخط الزمني المعتمد للمراجعة', 'draft', 'tab label + panel heading, ''Canonical'' -> ''Official'''),
  ('review.ws.timelineNote', 'Submission, resubmission, review, comment, and Compliance handoff events from review_timeline().', 'أحداث التقديم وإعادة التقديم والمراجعة والتعليقات وإحالة الامتثال من review_timeline().', 'draft', 'timeline tab footer note, dropped ''Canonical'''),
  ('review.ws.timelineUnavailable', 'Review timeline not available.', 'الخط الزمني للمراجعة غير متاح.', 'draft', 'timeline tab error banner title'),
  ('review.ws.timelineUnavailableBody', 'The review timeline is not available in this environment. We do not make up a timeline to fill the gap.', 'الخط الزمني للمراجعة غير متاح في هذه البيئة؛ لن يتم إنشاء تسلسل زمني بديل غير موثّق.', 'draft', 'timeline tab error banner body'),
  ('review.ws.trace.unavailable', 'Not available', 'غير متاح', 'draft', 'finding-trace unavailable-link label, reused for prior-decision empty state'),
  ('review.ws.unauthBody', 'You need an allowed role — review, planning, operations, audit, leadership, or the assigned inspector — with matching scope, to open this review. Being visible in navigation does not mean you have access.', 'تحتاج إلى دور مسموح به — مراجعة أو تخطيط أو عمليات أو تدقيق أو قيادة أو المفتش المعيّن — بنطاق مطابق، لفتح هذه المراجعة. ظهورها في التنقل لا يعني أن لديك صلاحية الوصول.', 'draft', 'unauthorized banner on the review detail page (dropped ''workspace'')'),
  ('risk.wb.banner.body', 'Drafts check that weights add up and that bands match the Risk Studio, then publish through maker-checker. Published versions can''t be changed. No value is set here that the approved structure doesn''t require.', 'تتحقق المسودات من أن مجموع الأوزان صحيح وأن النطاقات تطابق استوديو المخاطر، ثم تُنشر عبر آلية المُعدّ/المعتمد. لا يمكن تغيير الإصدارات المنشورة. لا تُحدَّد هنا أي قيمة لا يتطلبها الهيكل المعتمد.', 'draft', 'Risk model workbench banner body'),
  ('risk.wb.banner.title', 'Draft layer.', 'طبقة المسودات.', 'draft', 'Risk model workbench banner'),
  ('risk.wb.empty.body', 'No risk models exist in your allowed scope. Create a draft to begin the maker-checker lifecycle.', 'لا توجد نماذج مخاطر ضمن نطاقك المسموح به. أنشئ مسودة لبدء دورة المُعدّ/المعتمد.', 'draft', 'Risk model workbench empty state'),
  ('risk.wb.immutable', 'Published versions can''t be changed', 'لا يمكن تغيير الإصدارات المنشورة', 'draft', 'Risk model workbench'),
  ('risk.wb.off', 'The risk-model draft layer is not turned on here; live risk settings are still edited on the Risk Studio.', 'طبقة مسودات نماذج المخاطر غير مفعّلة هنا؛ لا تزال إعدادات المخاطر الفعّالة تُحرَّر في استوديو المخاطر.', 'draft', 'Risk workbench off-flag boundary'),
