  ('visit.actions.cutoffBody', 'The system checks the visit window again when you submit. You can cancel or reschedule until {cutoff} (Asia/Riyadh). Reassignment has no time limit.', 'يتحقق النظام من موعد الزيارة مرة أخرى عند الإرسال. يمكنك الإلغاء أو إعادة الجدولة حتى {cutoff} (توقيت الرياض). لا يوجد حد زمني لإعادة التكليف.', 'draft', 'Simplified from a formal ''transaction time / 720-hour gate'' sentence'),
  ('visit.actions.cutoffTitle', 'Cutoff for cancelling and rescheduling', 'الموعد النهائي للإلغاء وإعادة الجدولة', 'draft', 'Info banner title above the management actions'),
  ('visit.actions.duplicateWhy', 'Duplicate creates a new Draft with planning fields only (PLN-REQ-011).', 'يُنشئ التكرار مسودة جديدة تتضمن حقول التخطيط فقط (PLN-REQ-011).', 'draft', 'Caption under the Duplicate visit action'),
  ('visit.actions.executionStarted', 'Execution already started ({state}) — cancel and reschedule are locked (M02-006)', 'بدأ التنفيذ بالفعل ({state}) — الإلغاء وإعادة الجدولة مُقفلان (M02-006)', 'draft', 'Unused-in-JSX string kept in sync for consistency'),
  ('visit.actions.heading', 'Management actions — only valid changes are allowed', 'إجراءات الإدارة — يُسمح فقط بالتغييرات الصالحة', 'draft', 'Heading over the visit management-actions panel'),
  ('visit.actions.repackageBtn', 'Change checklist', 'تغيير قائمة التفتيش', 'draft', 'Button verb aligned with the already-renamed ''checklist'' label (was ''Repackage'')'),
  ('visit.actions.scheduleLockedWhy', 'locked — execution already started ({state}). Only published, new visits can be rescheduled, changed, or cancelled (M02-006/008)', 'مُقفل — بدأ التنفيذ بالفعل ({state}). يمكن فقط إعادة جدولة أو تغيير أو إلغاء الزيارات المنشورة والجديدة (M02-006/008)', 'draft', 'Explains why schedule/type/cancel actions are blocked'),
  ('visit.actions.zoneUnavailable', 'Not available in this state', 'غير متاح في هذه الحالة', 'draft', 'Zone heading for final-state actions panel'),
  ('visit.ai.description', 'A summary of the visits you can access. It can''t change a visit, assignment, state, or campaign.', 'ملخص للزيارات التي يمكنك الوصول إليها. لا يمكنه تغيير أي زيارة أو تكليف أو حالة أو حملة.', 'draft', 'Contextual AI panel description; dropped ''authorized scope'''),
