  ('visit.ai.unavailable', 'AI summary not available — nothing was generated or changed.', 'ملخص الذكاء الاصطناعي غير متاح — لم يتم إنشاء أو تغيير أي شيء.', 'draft', 'AI widget boundary/unavailable label'),
  ('visit.att.fileLabel', 'Attach a file (planner or operations only)', 'إرفاق ملف (للمخطط أو التشغيل فقط)', 'draft', 'Attachment upload field label; removed leaked ''RLS-enforced'' jargon'),
