  ('visit.detail.unauthorized.body', 'You need planning access to view visit details.', 'يلزم صلاحية تخطيط لعرض تفاصيل الزيارة.', 'draft', 'Was ''Planning-owned visit details require an authorized planning capability.'''),
  ('visit.elig.samePlanBlocked', 'Bulk edit only works within one Plan. It isn''t available across different Plans yet.', 'التعديل الجماعي يعمل فقط ضمن خطة واحدة. غير متاح بعد عبر خطط مختلفة.', 'draft', 'Disabled-control tooltip for cross-Plan bulk edit'),
  ('visit.err.reasonRequired', 'Something went wrong with this request. Nothing changed.', 'حدث خطأ في هذا الطلب. لم يتغيّر شيء.', 'draft', 'Bulk-action error; removed leaked ''mutation request identity'' jargon'),
  ('visit.err.reasonsUnavailable', 'Cancellation reasons aren''t available right now (ERR-OPS-001) — nothing was changed.', 'أسباب الإلغاء غير متاحة الآن (ERR-OPS-001) — لم يتغيّر شيء.', 'draft', 'Bulk-cancel error when reason lookup fails'),
  ('visit.ledger.frozenSelection', 'The list of visits is locked while this runs', 'قائمة الزيارات مُقفلة أثناء تنفيذ هذا الإجراء', 'draft', 'Busy-progress caption next to the applying-to-N-visits message'),
