  ('visit.list.scope', 'Showing {shown} of {total} — based on your access', 'يعرض {shown} من {total} — بحسب صلاحياتك', 'draft', 'Row-count caption; removed leaked ''RLS-scoped'' jargon'),
  ('visit.list.unauthorized.body', 'You need planning access to manage visits.', 'يلزم صلاحية تخطيط لإدارة الزيارات.', 'draft', 'Was ''Planning-owned visit management requires an authorized planning capability.'''),
